    t[19238] = { name = "Віщування Сейджа №3", fen = "An enemy from your past will soon become an ally.", fua = "Ворог із твого минулого невдовзі стане союзником." }
    t[19239] = { name = "Віщування Сейджа №4", fen = "You will be fortunate in everything you put your hands to.", fua = "Тобі щаститиме в усьому, за що візьмешся." }
    t[19240] = { name = "Віщування Сейджа №5", fen = "Someone is speaking well of you.", fua = "Хтось говорить про тебе добре." }
    t[19241] = { name = "Віщування Сейджа №6", fen = "Be cautious when landing in unfamiliar territory.", fua = "Будь обережним, потрапляючи на незнайому територію." }
    t[19242] = { name = "Віщування Сейджа №7", fen = "Avoid taking unnecessary gambles.", fua = "Уникай непотрібних ризиків." }
    t[19243] = { name = "Віщування Сейджа №8", fen = "You will receive a fortune.", fua = "Ти отримаєш статок." }
    t[19244] = { name = "Віщування Сейджа №9", fen = "Your first love and last love is self-love.", fua = "Твоє перше й останнє кохання - це любов до себе." }
    t[19245] = { name = "Віщування Сейджа №10", fen = "Rest is a good thing, but boredom is its brother.", fua = "Відпочинок - добра річ, але нудьга йому брат." }
    t[19246] = { name = "Віщування Сейджа №11", fen = "Those with simple tastes are always satisfied with the best.", fua = "Ті, хто має прості смаки, завжди задоволені найкращим." }
    t[19247] = { name = "Віщування Сейджа №12", fen = "Let not the tides of war wash you away.", fua = "Не дай хвилям війни змити тебе геть." }
    t[19248] = { name = "Віщування Сейджа №13", fen = "You leave your adversaries speechless.", fua = "Ти залишаєш своїх супротивників безмовними." }
    t[19249] = { name = "Віщування Сейджа №14", fen = "You have a good eye for spotting hypocrisy.", fua = "Ти маєш гостре око на лицемірство." }
    t[19250] = { name = "Віщування Сейджа №15", fen = "One learns most when teaching others.", fua = "Найбільше навчаєшся, коли навчаєш інших." }
    t[19251] = { name = "Віщування Сейджа №16", fen = "The time will soon come for you to make a choice in a pressing matter.", fua = "Невдовзі настане час прийняти рішення в нагальній справі." }
    t[19252] = { name = "Віщування Сейджа №18", fen = "Accept the next proposition you hear.", fua = "Прийми наступну пропозицію, яку почуєш." }
    t[19253] = { name = "Віщування Сейджа №17", fen = "Never punt a gnome without due cause.", fua = "Ніколи не штурхай ґнома без вагомої причини." }
    t[19254] = { name = "Віщування Сейджа №21", fen = "Divine Shields and Hearthstones do not make a hero heroic.", fua = "Божественні щити й камені повернення не роблять героя героїчним." }
    t[19255] = { name = "Віщування Сейджа №22", fen = "An answer in blue is always true.", fua = "Відповідь у блакитному завжди правдива." }
