    t[43599] = { name = "Великий Ведмідь Blizzard", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[43608] = "Летка олія Мідного Кігтя"
    t[43609] = { name = "Купа кісток", fen = "A fallen soldier, stripped of flesh.", fua = "Полеглий вояк, позбавлений плоті." }
    t[43610] = { name = "Покинутий Шолом", fen = "A battleworn Alliance helm.", fua = "Побитий у боях шолом Альянсу." }
    t[43614] = "Розбита Пляшечка Еліксиру Гніву"
    t[43615] = "Бойовий Обладунок Саурфанга"
    t[43616] = { name = "Покинута Броня", fen = "A pierced Alliance breastplate.", fua = "Пробитий нагрудник Альянсу." }
    t[43620] = "Розбита Пляшечка Еліксиру Чарівної Сили"
    t[43621] = "Розбита Пляшечка Еліксиру Ноґґенфоґґера"
    t[43622] = "Морозосталева скринька"
    t[43624] = "Титанова Скринька"
    t[43626] = "Смаколик для Улюбленця"
    t[43627] = { name = "Золота Монета Тралла", fen = "Grom, may you rest well, old friend.", fua = "Громе, спочивай із миром, давній друже." }
    t[43628] = { name = "Золота Монета Леді Джайни Праудмур", fen = "Arthas, my love, please come back to me.", fua = "Артасе, коханий, прошу, повернися до мене." }
    t[43629] = { name = "Золота Монета Утера Світлоносного", fen = "Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.", fua = "Юний Артас має навчитися терпіння, щоб гартувати свою силу. Я молитимуся, щоб одного дня він навчився вести за собою турботою, а не примусом." }
    t[43630] = { name = "Золота Монета Тіріона Фордрінга", fen = "It is my wish that my dear Taelan will grow strong enough to defend the people he cares for.", fua = "Я бажаю, щоб мій любий Телан виріс достатньо сильним, аби захищати тих, хто йому дорогий." }
    t[43631] = { name = "Золота Монета Терона", fen = "Wishes are a fool's pastime. Take this coin as payment for your precious Eye.", fua = "Бажання -- забавка для дурнів. Візьми цю монету як плату за твоє коштовне Око." }
    t[43632] = { name = "Золота Монета Сильвани Віндраннер", fen = "I hope my sisters and I can grow up and get married together. This coin appears to be very old.", fua = "Сподіваюся, ми із сестрами виростемо й вийдемо заміж разом. Ця монета, схоже, дуже давня." }
    t[43633] = { name = "Золота Монета Принца Кель'таса Сонцеходи", fen = "That young apprentice Jaina is quite attractive for a human. I hope she recognizes my elegance and power.", fua = "Ця юна учениця Джайна доволі приваблива як на людину. Сподіваюся, вона помітить мою елегантність і могутність." }
    t[43634] = { name = "Золота Монета Леді Катрани Престор", fen = "Listen, little wishing fountain. You'll give me all your power if you know what's good for you.", fua = "Слухай-но, маленький фонтане бажань. Ти віддаси мені всю свою силу, якщо тобі дороге твоє благо." }
    t[43635] = { name = "Золота Монета Кел'Тузада", fen = "Sometimes... I wish someone would come along and just give me a big, long hug.", fua = "Іноді... я хочу, щоб хтось прийшов і просто міцно й довго мене обійняв." }
    t[43636] = { name = "Золота Монета Хромі", fen = "Just once, I wish someone would greet me without making a stupid joke about gnomes or time travel.", fua = "Хоч раз я хотіла б, щоб мене привітали, не вставивши дурного жарту про гномів чи мандри в часі." }
    t[43637] = { name = "Золота Монета Бранна Бронзборода", fen = "Brann Bronzebeard was here.", fua = "Бранн Бронзборід був тут." }
    t[43638] = { name = "Золота Монета Аругала", fen = "I wish someday to retire to my own tidy little estate, with a bunch of pet dogs to keep me company.", fua = "Я мрію колись усамітнитися у своєму власному охайному маленькому маєтку, де зграйка собак складатиме мені товариство." }
    t[43639] = { name = "Золота Монета Артаса", fen = "Already, I've a kingdom in my prospects, a land to rule. What to ask for?  Perhaps a frozen scone...", fua = "У мене вже є королівство на видноколі, земля, якою я правитиму. Чого ж побажати? Хіба що крижаного коржика..." }
    t[43640] = { name = "Золота Монета Архімонда", fen = "I wish to know how you survived my wrath, little fountain.", fua = "Я хочу знати, як ти пережив мій гнів, маленький фонтане." }
    t[43641] = { name = "Золота Монета Андуїна Рінна", fen = "I wish I would grow up, it feels like I've been 10 for years.", fua = "Хотів би я вирости, відчуття таке, ніби мені вже багато років по десять." }
    t[43643] = { name = "Срібна Монета Принца Маґні Бронзборода", fen = "I hope that my father and brothers outlive me. I'll not make much of a king.", fua = "Сподіваюся, мій батько і брати переживуть мене. З мене вийде поганенький король." }
    t[43644] = { name = "Срібна Монета Селянина", fen = "I'm so forgetful! I wish I had a better memory. Wait, didn't I already throw a coin into here?", fua = "Який же я забудькуватий! Хотів би я мати кращу пам'ять. Стривай, хіба я вже не кидав сюди монету?" }
    t[43645] = { name = "Погнутий Рибальський Гачок", fen = "Looks like someone tried to fish in this fountain. Who would do such a thing?", fua = "Схоже, хтось намагався вудити в цьому фонтані. Хто б таке робив?" }
    t[43646] = "Фонтанна Золота Рибка"
    t[43647] = "Мерехтливий Гольян"
    t[43652] = "Слизький Вугор"
    t[43653] = { name = "Надкушена Риба", fen = "Small tooth marks can be seen on the carcass.", fua = "На тушці видніються дрібні сліди зубів." }
    t[43654] = "Фоліант Світанку"
    t[43655] = "Книга виживання"
    t[43656] = "Фоліант Королів"
    t[43657] = "Королівський Путівник Шляхів Втечі"
    t[43658] = { name = "Частково Заіржавілий Напилок", fen = "The file has a slight green tinge to it.", fua = "Напилок має легкий зеленавий відтінок." }
    t[43660] = "Посібник Пожирача Вогню"
    t[43661] = "Книга зірок"
    t[43662] = { name = "Сокира Грабіжника", fen = "You would expect this axe to be exceptionally sharp. It's not. The vrykul must have been relying upon his immense strength to hew through his foes.", fua = "Ви очікували б, що ця сокира надзвичайно гостра. Це не так. Врайкул, мабуть, покладався на свою величезну силу, аби рубати ворогів." }
    t[43663] = "Грозоскутий Фоліант"
    t[43664] = "Посібник Хмар"
    t[43665] = { name = "Розбите Серце Керістрази", fen = "A tragic end to a sad tale. If only Malygos's abuse of Keristrasza hadn't driven her insane.", fua = "Трагічний кінець сумної історії. Якби ж знущання Малігоса над Керистразою не довели її до божевілля." }
    t[43668] = { name = "Налаштовувач Силових Ліній", fen = "You're not quite sure what to make of it. It definitely seethes with arcane magic, but how can something so small be so important?", fua = "Ви не зовсім розумієте, що про це думати. Він безперечно вирує таємною магією, але як щось таке мале може бути таким важливим?" }
    t[43669] = { name = "Медальйон Спочилої Королеви", fen = "The only reminder that King Ymiron had of his love, Queen Angerboda.", fua = "Єдина згадка, яку король Імірон зберіг про своє кохання, королеву Анґербоду." }
    t[43670] = { name = "Зачароване Тікі Пророка", fen = "It seems to have lost all of its mojo with the demise of its bearer.", fua = "Схоже, воно втратило все своє моджо зі смертю свого власника." }
    t[43671] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43672] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43673] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43674] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43675] = { name = "Срібна Монета Фандрала Стаґгельма", fen = "The War of the Shifting Sands... I wish I could forget it ever happened.", fua = "Війна Мінливих Пісків... Хотів би я забути, що вона взагалі сталася." }
    t[43676] = { name = "Срібна Монета Арканіста Доана", fen = "Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...", fua = "Ох, чому ж ти мене не помічаєш? Аббендіс, я пішов би за тобою куди завгодно. Якби ж ти мене помітила..." }
    t[43677] = { name = "Срібна Монета Верховного Майстра Меккаторка", fen = "How does this fountain even work? I wonder if I could make one.", fua = "Як же цей фонтан узагалі працює? Цікаво, чи зміг би я такий змайструвати." }
    t[43678] = { name = "Срібна Монета Антонідаса", fen = "Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.", fua = "Дай мені сили прийняти те, чого я не можу змінити, мужності змінити те, що можу, і мудрості, щоб відрізнити одне від одного." }
    t[43679] = { name = "Срібна Монета Мурадіна Бронзборода", fen = "May the Holy Light protect us on our expedition to the frozen north.", fua = "Нехай Святе Світло береже нас у нашій виправі на замерзлу північ." }
    t[43680] = { name = "Срібна Монета Короля Варіана Рінна", fen = "I wish the uprising back at home would settle itself soon. I wouldn't want anyone to be hurt.", fua = "Хотів би я, щоб повстання вдома скоро вгамувалося. Не хочу, щоб хтось постраждав." }
    t[43681] = { name = "Срібна Монета Короля Теренаса Менетіла", fen = "May my son Arthas always act in the best interest of his people.", fua = "Нехай мій син Артас завжди діє в найкращих інтересах свого народу." }
    t[43682] = { name = "Срібна Монета Короля Анастеріана Сонцеходи", fen = "I hope young Kael'thas realizes that one day he must lead our people.", fua = "Сподіваюся, юний Кель'тас усвідомлює, що одного дня йому доведеться вести наш народ." }
    t[43683] = { name = "Срібна Монета Хадґара", fen = "Turalyon and Alleria, wherever you are, may you be well.", fua = "Тураліоне й Аллеріє, де б ви не були, нехай у вас усе буде гаразд." }
    t[43684] = { name = "Срібна Монета Медіва", fen = "<You sense the ringing of three tones in your head, the third barely audible under the others' din.>", fua = "<У вашій голові лунають три тони, третій з яких ледь чутний за гомоном решти.>" }
    t[43685] = { name = "Срібна Монета Маїв Шедоусонг", fen = "Where's Illidan?", fua = "Де Іллідан?" }
    t[43686] = { name = "Срібна Монета Аллерії", fen = "May my sisters realize their full potential, the name Windrunner known as result of their deeds.", fua = "Нехай мої сестри розкриють увесь свій потенціал, і нехай ім'я Віндраннер прославиться їхніми звершеннями." }
    t[43687] = { name = "Срібна Монета Еґвінн", fen = "I really wish you mages would get your heads out from inside your own... books.", fua = "Як же я хочу, щоб ви, маги, нарешті повитягали голови зі своїх... книжок." }
    t[43693] = { name = "Залишок Моджо Акалі", fen = "Hard to believe that this is all that is left of the once mighty rhino god.", fua = "Важко повірити, що це все, що лишилося від колись могутнього бога-носорога." }
    t[43694] = { name = "Утоплений Щур", fen = "Looks like falling in the soup pot did not work out so well this time.", fua = "Схоже, падіння в казан із супом цього разу обернулося не надто вдало." }
    t[43695] = { name = "Напівповна Пляшка В'язничного Самогону", fen = "Also useful for removing paint.", fua = "Також придатний для змивання фарби." }
    t[43696] = { name = "Напівпорожня Пляшка В'язничного Самогону", fen = "Also useful for removing paint.", fua = "Також придатний для змивання фарби." }
    t[43697] = { name = "Артефакт зі Світу Натрезімів", fen = "What strange construction. It must be one of the most alien-looking objects you've ever seen.", fua = "Яка дивна будова. Це, певно, один із найхимерніших предметів, які ви будь-коли бачили." }
    t[43698] = { name = "Велетенський Каналізаційний Щур", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[43699] = { name = "Диск Прокляття Плоті", fen = "There's information on this thing? What? There's no writing!", fua = "На цій штуці є інформація? Що? Тут же нічого не написано!" }
    t[43701] = { name = "Мідна Монета Піхотинця", fen = "Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...", fua = "Хотів би я, щоб мій обов'язок був, як у мого кузена, -- безтурботно тягати дрова, і нічого більше..." }
    t[43702] = { name = "Мідна Монета Алонсуса Фаола", fen = "One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.", fua = "Колись я сподіваюся понести шлях Світла простому люду й навчити їх цінувати Три Чесноти." }
    t[43703] = { name = "Мідна Монета Ансірема", fen = "I wish for happiness and acceptance for my daughter. She feels so out of place here...", fua = "Я бажаю своїй доньці щастя й визнання. Вона почувається тут такою чужою..." }
    t[43704] = { name = "Мідна Монета Аттумена", fen = "Can I have a more comfortable saddle?  My hindquarters ache.", fua = "Можна мені зручніше сідло? У мене болить заднє місце." }
    t[43705] = { name = "Мідна Монета Даната", fen = "I hope a troll dies, right... NOW.", fua = "Сподіваюся, тролль помре прямо... ЗАРАЗ." }
    t[43706] = { name = "Блискуча Мідна Монета Дорни", fen = "I wish that that jerk Arthas would fall into a pile of magnataur doody!", fua = "Хочу, щоб той бовдур Артас гепнувся в купу магнатаврового гною!" }
    t[43707] = { name = "Мідна Монета Ейтрігга", fen = "May Tirion's quest here in Northrend end with success, or may he die honorably in battle.", fua = "Нехай похід Тіріона тут, у Нордсколі, увінчається успіхом, або ж нехай він з честю загине в бою." }
    t[43708] = { name = "Мідна Монета Еллінга Тріаса", fen = "Being a rogue is hard work.  Someday I hope to pursue my life's one true passion...", fua = "Бути розбійником -- важка робота. Колись я сподіваюся віддатися єдиній справжній пристрасті свого життя..." }
    t[43709] = { name = "Мідна Монета Фалстада Дикомолота", fen = "I hope I end up in another book eventually.", fua = "Сподіваюся, колись я потраплю ще в якусь книгу." }
    t[43710] = { name = "Мідна Монета Генна", fen = "Pah, the fountains in Gilneas could grant ten times as many wishes as Dalaran's!", fua = "Ха, фонтани в Ґілнеасі могли б виконати вдесятеро більше бажань, ніж даларанські!" }
    t[43711] = { name = "Мідна Монета Ініго", fen = "I wish I had my father back...", fua = "Хотів би я повернути свого батька..." }
    t[43712] = { name = "Мідна Монета Красуса", fen = "My prayers go out to my brothers and sisters who still suffer in the heart of Grim Batol. I WILL free them.", fua = "Мої молитви линуть до братів і сестер, які досі страждають у серці Грім-Батолу. Я ЗВІЛЬНЮ їх." }
    t[43713] = { name = "Мідна Монета Крилла", fen = "Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it'll explode.", fua = "Бум. Ну, бум? Я хочу бум. Гайда, бум! Ця монета, мабуть, зламана, цікаво, чи вона вибухне." }
    t[43714] = { name = "Мідна Монета Ландро Лонгшота", fen = "I wish I'd kept that coin...", fua = "Шкода, що я не лишив собі ту монету..." }
    t[43715] = { name = "Мідна Монета Молока", fen = "Just once -- that's all I ask for, just once -- let the lass ride with me...", fua = "Лише раз -- це все, чого я прошу, лише раз -- дозволь дівчині поїхати верхи зі мною..." }
    t[43716] = { name = "Мідна Монета Меркі", fen = "I wish the water in Northrend wasn't so cold, it makes me sleepy.", fua = "Хотів би я, щоб вода в Нордсколі не була такою холодною, від неї мене хилить на сон." }
    t[43717] = { name = "Мідна Монета Принцеси Калії Менетіл", fen = "I hope that handsome nobleman Lord Prestor notices me! He's so dreamy!", fua = "Сподіваюся, цей вродливий вельможа лорд Престор мене помітить! Він такий чарівний!" }
    t[43718] = { name = "Мідна Монета Рядового Маркуса Джонатана", fen = "I wish to grow a glorious, bushy mustache someday.", fua = "Хочу колись відростити пишні, кошлаті вуса." }
    t[43719] = { name = "Блискуча Мідна Монета Саландрії", fen = "Someday, I'm gonna be more powerful than all of these mages!", fua = "Колись я стану могутнішою за всіх цих магів!" }
    t[43720] = { name = "Мідна Монета Зброєносця Роу", fen = "I hope I can get transferred out of Stormwind eventually and see Cersei again. Nothing good ever happens in this city.", fua = "Сподіваюся, мене врешті переведуть зі Штормовому й я знову побачу Серсі. У цьому місті ніколи не стається нічого доброго." }
    t[43721] = { name = "Мідна Монета Сталвана", fen = "You mages refuse to provide me that which hastens the inevitable fate of two people in love, when only one is too naive to see it. I wish you all ruin.", fua = "Ви, маги, відмовляєтеся дати мені те, що пришвидшить неминучу долю двох закоханих, коли лише одна з них надто наївна, щоб це побачити. Бажаю вам усім загибелі." }
    t[43722] = { name = "Мідна Монета Вериси", fen = "Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...", fua = "Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna..." }
    t[43723] = { name = "Мідна Монета Варгота", fen = "I wish Captain Sanders would hurry up with my shipment of wine.", fua = "Хотів би я, щоб капітан Сандерс уже нарешті привіз мою партію вина." }
    t[43724] = { name = "Небесний Рубіновий Перстень", fen = "Ring? It's more like a necklace and a heavy one at that!", fua = "Перстень? Це радше намисто, та ще й важке!" }
    t[43725] = "Обвуглений Гліф"
    t[43726] = { name = "Непотрібна Корона Ануб'арака", fen = "The crypt lord still carried it though he lost his royal title long ago when he entered the service of the Lich King.", fua = "Володар склепів досі носив її, хоча давно втратив свій королівський титул, коли вступив на службу до Короля-Ліча." }
    t[43821] = { name = "Висохлий Мозок Безликого", fen = "Um... it's still pulsing!", fua = "Гм... він досі пульсує!" }
    t[43823] = { name = "Голова Ціанігози", fen = "This'll make a nice trophy for someone's wall.", fua = "З цього вийде гарний трофей для чиєїсь стіни." }
    t[43825] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43826] = "Обвуглений Гліф"
    t[43827] = { name = "Обвуглений Гліф", fen = "While it appears this glyph was burned horribly and no longer contains any magic, a vendor might not know the difference...", fua = "Хоча цей гліф, схоже, страшенно обгорів і вже не містить жодної магії, торговець може й не помітити різниці..." }
    t[43850] = { name = "Подертий Сертифікат Власності", fen = "A deed to a pet well-loved.", fua = "Свідоцтво на щиро улюбленого улюбленця." }
    t[43851] = "Клапті Хутряного Одягу"
