    t[62558] = { name = "Картка Долі", fen = "You will hear the tinkling of golden coins.", fua = "Ти почуєш дзвін золотих монет." }
    t[62559] = { name = "Картка Долі", fen = "Trust in the Light, but watch your mount.", fua = "Вір у Світло, та припильнуй своє верхове." }
    t[62560] = { name = "Картка Долі", fen = "Never stand in the shadow of dragons.", fua = "Ніколи не стій у тіні драконів." }
    t[62561] = { name = "Картка Долі", fen = "The road to Blackrock Mountain is paved with good intentions.", fua = "Дорога до гори Блекрок вимощена добрими намірами." }
    t[62562] = { name = "Картка Долі", fen = "Many raid wipes are in your immediate future.", fua = "У твоєму найближчому майбутньому — багато вайпів у рейді." }
    t[62563] = { name = "Картка Долі", fen = "Epics are like children; none are so wonderful as your own.", fua = "Епічні речі — як діти: жодна не буває такою чудовою, як власна." }
    t[62564] = { name = "Картка Долі", fen = "Experience, honor points and faction reputation are in the days ahead.", fua = "Досвід, очки честі та репутація фракції чекають на вас попереду." }
    t[62565] = { name = "Картка Долі", fen = "Your greatest fortune is in the friends you have.  Especially tanks.", fua = "Твій найбільший скарб — це твої друзі. Особливо танки." }
    t[62566] = { name = "Картка Долі", fen = "The future looks cataclysmic.", fua = "Майбутнє виглядає катаклізмічним." }
    t[62567] = { name = "Картка Долі", fen = "Find beauty in ordinary things. Vendor them for cash.", fua = "Знаходь красу у звичайних речах. А тоді спродуй їх торговцю за готівку." }
    t[62568] = { name = "Картка Долі", fen = "One who promises to go on a blind date is bound on pickup.", fua = "Хто обіцяє піти на побачення наосліп, прив'язується щойно його підбереш." }
    t[62569] = { name = "Картка Долі", fen = "A Shaman's blessing is elementary.", fua = "Благословення шамана — справа стихійна." }
    t[62570] = { name = "Картка Долі", fen = "Your outlook looks bright, unless you run into Deathwing.", fua = "Твоє майбутнє світле, хіба що тобі трапиться Дезвінг." }
    t[62571] = { name = "Картка Долі", fen = "You have a good chance to roll 100 in the near future.", fua = "Найближчим часом маєш добрі шанси викинути 100." }
    t[62572] = { name = "Картка Долі", fen = "You will develop a great sense of relaxation (and patience) from the fishing profession.", fua = "Риболовля подарує тобі глибоке відчуття спокою (і терпіння)." }
    t[62573] = { name = "Картка Долі", fen = "You will someday be able to afford that mount.", fua = "Колись ти зможеш дозволити собі того скакуна." }
    t[62574] = { name = "Картка Долі", fen = "IT IS TIME TO REORDER! For more fortunes, contact F.B. Krazzlestix, Bilgewater Harbor. Bulk discounts available for a small fee.", fua = "ЧАС ЗАМОВЛЯТИ ЩЕ! Щоб отримати більше передбачень, звертайтеся до Ф.Б. Кразлстікса, гавань Більджвотер. За невелику плату доступні знижки на гуртові замовлення." }
    t[62575] = { name = "Картка Долі", fen = "You have many hidden talents. You will gain more with experience.", fua = "У тебе багато прихованих талантів. З досвідом їх стане ще більше." }
    t[62576] = { name = "Картка Долі", fen = "He who fights an army is a martyr; he who fights five is elite.", fua = "Хто б'ється проти армії — мученик; хто б'ється проти п'ятьох — еліта." }
    t[62577] = { name = "Картка Долі", fen = "A light heart carries you through bad Battlegrounds.", fua = "Легке серце проведе тебе крізь невдалі поля бою." }
    t[62578] = { name = "Картка Долі", fen = "All of the effort you are making is worth the repair costs.", fua = "Усі ваші зусилля варті витрат на ремонт." }
    t[62579] = { name = "Картка Долі", fen = "Never trust a troll. Or a rogue. Especially a troll rogue.", fua = "Ніколи не довіряй тролю. Чи розбійнику. А надто тролю-розбійнику." }
    t[62580] = { name = "Картка Долі", fen = "Disbelief destroys the magic.", fua = "Зневіра руйнує магію." }
    t[62581] = { name = "Картка Долі", fen = "Now is the time to try something new. Perhaps a new tradeskill.", fua = "Саме час спробувати щось нове. Можливо, нове ремесло." }
    t[62582] = { name = "Картка Долі", fen = "Every herb blooms in its own sweet time. Then you pick it!", fua = "Кожна трава розквітає у свій час. А тоді ви її зриваєте!" }
    t[62583] = { name = "Картка Долі", fen = "Go take a rest. You deserve it. Remember to rest in an inn though!", fua = "Іди відпочинь. Ти це заслужив. Тільки не забудь відпочивати в заїзді!" }
    t[62584] = { name = "Картка Долі", fen = "He who expects a wipe will never be disappointed.", fua = "Хто очікує вайпу, той ніколи не розчарується." }
    t[62585] = { name = "Картка Долі", fen = "Never look up when there are flying mounts above you.", fua = "Ніколи не дивися вгору, коли над тобою літальні маунти." }
    t[62586] = { name = "Картка Долі", fen = "You will inherit a large sum of money. You will blow it at the Auction House.", fua = "Ти успадкуєш чималеньку суму грошей. І спустиш її на аукціоні." }
    t[62587] = { name = "Картка Долі", fen = "Someone nearby wants to /flirt with you.", fua = "Хтось поблизу хоче /flirt із тобою." }
    t[62588] = { name = "Картка Долі", fen = "Your talents will be recognized and rewarded. Provided your talent spec is good.", fua = "Твої таланти визнають і винагородять. За умови, що твоя спеціалізація вдала." }
    t[62589] = { name = "Картка Долі", fen = "Help! I'm being held prisoner in a fortune cookie bakery!", fua = "Рятуйте! Мене тримають у полоні в пекарні печива з передбаченнями!" }
    t[62590] = { name = "Картка Долі", fen = "The sun will shine tomorrow.", fua = "Завтра світитиме сонце." }
    t[62591] = { name = "Картка Долі", fen = "You will receive a gift from someone you hate.", fua = "Ти отримаєш подарунок від того, кого ненавидиш." }
    t[62592] = { name = "Обвуглена Високогірна Береза", fen = "This burnt wood gives off an unmistakable smell. It's no wonder the gryphons respond to it so easily.", fua = "Це обгоріле дерево випромінює неповторний запах. Не дивно, що грифони так легко на нього реагують." }
    t[62593] = { name = "Оживлений Намул", fen = "This sample continues to shift and stir.", fua = "Цей зразок продовжує ворушитися й вирувати." }
    t[62594] = { name = "Розбита Чаша", fen = "Gemstones appear to have been pried from its settings.", fua = "Здається, самоцвіти повисмикували з оправ." }
    t[62595] = { name = "Запорошена Ваза", fen = "Cracked, chipped, and old.", fua = "Тріснута, надщерблена й стара." }
    t[62596] = { name = "Земляний Гліф", fen = "An ancient word in a forgotten tongue, carved into rock.", fua = "Прадавнє слово забутою мовою, вирізьблене в камені." }
    t[62597] = { name = "Знаряддя Трога", fen = "It's a rock.", fua = "Це камінь." }
    t[62598] = { name = "Картка Долі", fen = "The beginning of wisdom is to desire it. The end of wisdom is to theorycraft.", fua = "Початок мудрості — прагнути її. Вершина мудрості — теорікрафтити." }
    t[62599] = { name = "Картка Долі", fen = "You will live a long, happy life with many resurrections along the way.", fua = "Ти проживеш довге, щасливе життя з багатьма воскресіннями на цьому шляху." }
    t[62600] = { name = "Картка Долі", fen = "The path of the faceroller is not the path to wisdom.", fua = "Шлях фейсролера — не шлях до мудрості." }
    t[62601] = { name = "Картка Долі", fen = "All that glitters is not gold.  But you can sell it for gold most of the time.", fua = "Не все те золото, що блищить. Та здебільшого це можна продати за золото." }
    t[62602] = { name = "Картка Долі", fen = "You will give someone a piece of your mind, which you can ill afford.", fua = "Ти комусь викладеш усе, що думаєш, хоч і не маєш на це права." }
    t[62603] = { name = "Картка Долі", fen = "When life gives you lemons, pay for repair costs.", fua = "Коли життя підкидає тобі лимони, плати за ремонт." }
    t[62604] = { name = "Картка Долі", fen = "A feather in the hand is worth a Levitate.", fua = "Краще перо в руці, ніж Левітація в небі." }
    t[62605] = { name = "Картка Долі", fen = "Your lucky numbers are: 4 8 15 16 23 42", fua = "Твої щасливі числа: 4 8 15 16 23 42" }
    t[62606] = { name = "Картка Долі", fen = "You have many friends and very few living enemies.", fua = "У тебе багато друзів і дуже мало живих ворогів." }
