    t[81216] = { name = "Духовні Гроші", fen = "A piece of golden paper with elaborate designs depicting items of great value.  Perhaps another spirit will find better use for it.", fua = "Аркуш золотого паперу з вишуканими візерунками, що зображують речі великої цінності. Можливо, інший дух знайде їм краще застосування." }
    t[81217] = { name = "Блискучий Черепаховий Панцир", fen = "This gleaming piece of turtle shell calls out to be carved into something lovely.", fua = "Цей блискучий шматок черепахового панцира так і просить, щоб із нього вирізьбили щось прекрасне." }
