    t[89202] = { name = "Насіння Раптолиста", fen = "The raptorleaf is a carnivorous plant which is known to devour virmen, hawks and other small creatures. It dies after a single meal, releasing seeds into the air and often leaving behind the remains of its catch.", fua = "Раптолист — хижа рослина, відома тим, що пожирає вірменів, яструбів та інших дрібних створінь. Вона гине після єдиної трапези, випускаючи насіння в повітря й часто лишаючи по собі останки своєї здобичі." }
