    t[91802] = { name = "Шворка Нефритового Пандаренського Змія", fen = "Teaches you how to summon this mount.  This is a flying mount.", fua = "Навчає вас прикликати це їздове створіння. Це летюче їздове створіння." }
    t[91803] = "Бульба Хрусткого Кореня"
    t[91806] = { name = "Нестабільна Скалка Порталу", fen = "Chaotic arcane energy crystallized from high-traffic portals. The soil of Sunsong Ranch will stabilize this energy, yielding a shard that can be broken on the farm to open a one-shot portal to a major city.", fua = "Хаотична потаємна енергія, що кристалізувалася з жвавих порталів. Ґрунт Ранчо Сонцеспіву стабілізує цю енергію, утворюючи скалку, яку можна розбити на фермі, щоб відкрити одноразовий портал до великого міста." }
    t[91807] = { name = "Голова Ора", fen = "The confusion of defeat is frozen on this disembodied right head of Or.", fua = "Збентеження від поразки застигло на цій відрубаній правій голові Ора." }
    t[91808] = { name = "Голова Дака", fen = "Dac's tongue still protrudes from his face in a final act of defiance at being defeated.", fua = "Язик Дака досі стирчить з його обличчя в останньому акті непокори перед поразкою." }
    t[91809] = { name = "Голова Рук'ри", fen = "A look of signature Kor'kron pride and defiance is forever emblazened on this orc's head.", fua = "Вираз характерної кор'кронської гордості та зухвалості навіки закарбувався на голові цього орка." }
    t[91810] = { name = "Голова Сніклфріца", fen = "The gas mask is still stuck on this head.", fua = "Протигаз досі застряг на цій голові." }
    t[91819] = { name = "Міцні Сильця на Журавлів", fen = "An expertly-woven snare, designed to capture the leg of a powerful crane.", fua = "Майстерно сплетені сильця, призначені впіймати ногу могутнього журавля." }
    t[91821] = { name = "Міцна Пастка на Тигрів", fen = "A tightly-wound trap, designed to capture and immobilize a large tiger.", fua = "Туго натягнута пастка, призначена впіймати та знерухомити великого тигра." }
