    t[92909] = { name = "Розплавлений Шлак Обладунку", fen = "Slow and steady doesn't win the brawl race.", fua = "Повільно й розважливо перегонів бійки не виграти." }
    t[92910] = { name = "Пом'ятий Оздоблений Кухоль для Пива", fen = "Appears to have been the final word in a heated spectator argument.", fua = "Схоже, він мав останнє слово в запеклій суперечці глядачів." }
