    t[92912] = { name = "Зламаний Самофланж", fen = "This would be worth a fortune intact, but someone has stepped on it.", fua = "Цілий, він коштував би цілий статок, але хтось на нього наступив." }
    t[92913] = { name = "Закривавлена Хустинка", fen = "A favor thrown in to the arena that gained new life as a bandage.", fua = "Дарунок, кинутий на арену, який отримав нове життя як пов'язка." }
    t[92914] = { name = "Запечатане Пиво Штормової Браги", fen = "Once impossible to find, now sold all across Azeroth.", fua = "Колись його було неможливо знайти, тепер продається по всьому Азероту." }
    t[92915] = { name = "Зламаний Спис Срібного Світанку", fen = "Jousting skills apparently do not translate to brawling.", fua = "Уміння в кінних двобоях, очевидно, не переносяться на бійки." }
    t[92916] = { name = "Вицвіла Боргова Розписка", fen = "The text is too faint to know how to claim the value of this note.", fua = "Текст надто тьмяний, щоб зрозуміти, як отримати за цією розпискою гроші." }
    t[92917] = { name = "Підроблена Водяна Квінтесенція", fen = "Nothing more than a bottle of water.", fua = "Не більше ніж пляшка води." }
    t[92918] = { name = "Підробка Видіння Саргераса", fen = "Upon closer inspection, this is a discarded Defias bandana that someone rolled up.", fua = "Якщо придивитися, це викинута бандана Беззаконників, яку хтось скрутив." }
    t[92919] = { name = "Дивна Пастка з Шипами", fen = "Left behind by a roaming Wolvar, it is unclear how to safely disarm this.", fua = "Покинута бродячим вольваром, і незрозуміло, як її безпечно знешкодити." }
    t[92920] = { name = "Подряпана Хроматична Драконяча Луска", fen = "Once priceless, now ruined by squabbling.", fua = "Колись безцінна, тепер зіпсована через чвари." }
    t[92921] = { name = "Стерта Відзнака Лейтенанта", fen = "Definitely antique, but of questionable usefulness.", fua = "Безперечно старовинна, але сумнівної корисності." }
    t[92922] = { name = "Стос Записок про Викуп", fen = "Each of these seem to be variation on extorting a fellow named Arechron.", fua = "Кожна з них, схоже, є варіацією вимагання грошей у хлопця на ім'я Аречрон." }
    t[92923] = { name = "Купа Іклів Шипогрива", fen = "You're not sure how Mankrik convinced someone to take this as collateral.", fua = "Ви не певні, як Манкрік переконав когось узяти це в заставу." }
    t[92924] = { name = "Неживий Самоцвіт Хаккарі", fen = "Any magic this once contained has long since faded.", fua = "Будь-яка магія, що колись у ньому містилася, давно вже згасла." }
    t[92925] = { name = "Розколотий Кристал Кіраджі", fen = "No longer resonates. Too bad - it's a red one.", fua = "Більше не резонує. Шкода - він був червоний." }
    t[92926] = { name = "Згаслий Сонячний Промінчик", fen = "Its once-bright glow is now only an occasional flicker.", fua = "Його колись яскраве сяйво тепер лише вряди-годи мерехтить." }
    t[92927] = { name = "Ящик Декоративних Сніжинок", fen = "Each of them is exactly the same as the next.", fua = "Кожна з них точнісінько така сама, як наступна." }
    t[92928] = { name = "Мило на Паличці", fen = "Revolutionary new product from Griftah and partners!", fua = "Революційний новий товар від Ґрифта та партнерів!" }
    t[92929] = { name = "Купа Латунних Гільз", fen = "Expensive looking, with \"H.N.\" carefully etched on the side of each one.", fua = "Виглядають дорого, з обережно витравленими на боці кожної ініціалами \"Г.Н.\"." }
    t[92930] = { name = "Реліквія Карабора", fen = "Inert and well-worn, but carefully preserved.", fua = "Бездіяльна та потерта, але дбайливо збережена." }
    t[92931] = { name = "Величезне Драконяче Ікло", fen = "Wagered and lost by a female orc warlord from the highlands.", fua = "Поставлене на кін і програне войовницею-орчинею з нагір'я." }
    t[92932] = { name = "Тріснута Маска Вуду", fen = "Made of completely ordinary wood, and has the initials \"Z.K.\" scrawled in several places.", fua = "Зроблена із цілком звичайного дерева, з нашкрябаними подекуди ініціалами \"З.К.\"." }
