    t[93956] = { name = "Різьблене Жало Зандаларського Отрутника", fen = "This engraved spider fang still has the venom sac attached, presumably for ritual poisoning.", fua = "На цьому гравірованому павучому іклі досі лишається мішечок з отрутою — імовірно, для ритуальних отруєнь." }
