    t[93958] = { name = "Викрадена Могуська Урна", fen = "The Saurok have repurposed this priceless, ten-thousand-year-old ceramic in to a chamber pot.", fua = "Сауроки перетворили цю безцінну десятитисячолітню кераміку на нічний горщик." }
    t[93959] = { name = "Самоцвітний Тарган Бруднолезих", fen = "Large, roughly cut gems are clumsily glued to each wing of this still-wiggling cockroach.", fua = "Великі, грубо огранені самоцвіти невправно приклеєні до кожного крила цього таргана, що досі звивається." }
    t[93960] = { name = "Самоцвітне Яйце Дияволозавра", fen = "Gifted from the Zandalari and encrusted with countless tiny gems, this egg depicts an ancient Mogu ruler.", fua = "Цей дарунок зандаларі, всипаний незліченними крихітними самоцвітами, зображує давнього могуського володаря." }
    t[93961] = { name = "Гудливий Самоцвіт Душ Шан'зе", fen = "You hear a faint, distant screaming when you hold the gem in your hand.", fua = "Тримаючи самоцвіт у руці, ви чуєте слабкий, далекий крик." }
