    t[95454] = { name = "Торбинка з Насінням Вітросічного Кактуса", fen = "The windshear cactus is covered in millions of fine needles which filter air as it passes through. Windwool fibers and scraps of material drifting in the breeze often collect on the cactus.", fua = "Вітросічний кактус укритий мільйонами тонких голок, що фільтрують повітря, яке крізь них проходить. На ньому часто осідають волокна вітрововни та клаптики тканини, що ширяють у бризі." }
