    t[98120] = { name = "Накладна на Доставку", fen = "A record of a large number of sealed containers being delivered to Orgrimmar.", fua = "Запис про доставку до Оґриммара великої кількості запечатаних контейнерів." }
    t[98121] = { name = "Булочка з Бурштинозерням", fen = "For some reason, fresh amberseeds were hard to come by this year.", fua = "З якоїсь причини свіже бурштинозерня цьогоріч було важко роздобути." }
    t[98122] = { name = "Камамбер з Молока Копитника", fen = "Milking a clefthoof is, as one might predict, extraordinarily difficult.", fua = "Подоїти копитника, як можна було передбачити, надзвичайно важко." }
