    t[98124] = { name = "Тарт з Кровоягодами", fen = "Bloodberries are actually quite common, but almost nobody goes to Quel'Danas to pick them anymore.", fua = "Кровоягоди насправді доволі поширені, але майже ніхто вже не ходить на Квел'Данас їх збирати." }
    t[98125] = { name = "Стругані Зангарські Трюфелі", fen = "Only a very small part of the Zangar Truffle is not poisonous. This is that part.", fua = "Лише зовсім маленька частина Зангарського трюфеля не отруйна. Це саме та частина." }
