    t[104287] = { name = "Перо Вітропера", fen = "The feathers of the Windfeather Crane are surprisingly light to the touch and will fly away with the slightest breeze.", fua = "Пера Вітроперого Журавля напрочуд легкі на дотик і відлітають від найменшого подмуху вітру." }
    t[104288] = { name = "Згущена Нефритова Імла", fen = "The Jademist Dancers are known to blend seamlessly into the fog surrounding the island.", fua = "Кажуть, що Танцівники Нефритової імли бездоганно зливаються з імлою, що огортає острів." }
    t[104290] = { name = "Липка Слиз Шовкопряда", fen = "The silkworms of the Timeless Isle have adapted a strange and very powerful silk used to catch prey.", fua = "Шовкопряди Позачасового острова виробляють дивну й дуже міцну шовкову нитку, щоб ловити здобич." }
    t[104291] = { name = "Роїнка Ґу'чі", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[104292] = { name = "Напівперетравлений Харч", fen = "This snake obviosly ate far too much in one sitting, as the food appears to be mostly intact and undigested.", fua = "Ця змія вочевидь з'їла надто багато за один раз, бо їжа здається переважно цілою й неперетравленою." }
    t[104293] = { name = "Панцир Шкряботуна", fen = "The shimmering shells of the spineclaws are useful for confusing would-be predators.", fua = "Мерехтливі панцирі колючокльоших стають у пригоді, щоб збивати з пантелику можливих хижаків." }
    t[104295] = { name = "Гармонійне Дикобразеня", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[104296] = { name = "Церемоніальна Роба Ордона", fen = "This ornate enchanted cloth can be broken down into useful materials.", fua = "Цю оздоблену зачаровану тканину можна розібрати на корисні матеріали." }
    t[104297] = "Палаючий Сигіл Ордоса"
    t[104299] = { name = "Спадне Полум'я", fen = "A white-hot shard found at the core of Cinderfall.", fua = "Розпечена добіла скалка, знайдена в осерді Попелопаду." }
    t[104303] = { name = "Дощовий Камінь", fen = "The playful water spirits of Pandaria have a curious connection to the weather.", fua = "Грайливі водяні духи Пандарії мають дивний зв'язок із погодою." }
    t[104304] = { name = "Камінь Хуртовини", fen = "High-ranking Ordon chanters can control the weather, ensuring that snow and rain never fall on the eternal fires of the Ordon Sanctuary.", fua = "Високопоставлені співці Ордона можуть керувати погодою, дбаючи, щоб сніг і дощ ніколи не падали на вічні вогні Святилища Ордона." }
    t[104305] = { name = "Попелястий Камінь", fen = "Before attacking, the Ordon yaungol will often summon a storm of ash to blind their foes.", fua = "Перед нападом яунголи Ордона часто викликають бурю попелу, щоб засліпити ворогів." }
    t[104306] = { name = "Камінь Заходу Сонця", fen = "An odd, and potentially quite dangerous, curio capable of stopping the flow of time in a small area.", fua = "Дивна й потенційно вельми небезпечна дивовижа, здатна спинити плин часу на невеликій ділянці." }
    t[104307] = { name = "Дух Нефритового Вогню", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[104314] = { name = "Драконячий П.И.Р.", fen = "Handcrafted by Grimthorn Redbeard.", fua = "Виготовлено вручну Грімторном Червонобородом." }
    t[104316] = { name = "Примарний Грог", fen = "Gives off an otherworldly aroma.", fua = "Видає потойбічний аромат." }
    t[104320] = { name = "Проклятий Талісман", fen = "The carvings on the face of the talisman depict a grotto filled with moss. If you squint, you can almost make out a face in the moss bed.", fua = "Різьба на лицьовому боці талісмана зображує грот, повний моху. Якщо примружитися, у мохистій постелі майже можна розгледіти обличчя." }
    t[104323] = { name = "Свинячий М'яч", fen = "An inflated pig's bladder wrapped in tough cow leather.", fua = "Надутий свинячий міхур, обтягнутий цупкою коров'ячою шкірою." }
