    t[107604] = { name = "Бездоганне Ікло зі Слонової Кістки", fen = "Lighter than iron and less brittle than bone, ivory is used in lightweight weaponry and is the favored medium of scrimshanders.", fua = "Легша за залізо й менш ламка за кістку, слонова кістка йде на легку зброю і є улюбленим матеріалом різьбярів." }
    t[107642] = { name = "Маска Вождя Черепа", fen = "This mask looks and smells as if it has been handed down from one mad chief to the next for several generations.", fua = "Ця маска виглядає і пахне так, наче її передавали від одного божевільного вождя до наступного протягом кількох поколінь." }
    t[107645] = { name = "Схрон Зброї Залізної Орди", fen = "Lots and lots of simple but deadly-looking weaponry.", fua = "Сила-силенна простої, але смертоносної на вигляд зброї." }
    t[107647] = { name = "Посібник з Експлуатації Прототипа Голіафа", fen = "Hefty. The tome is rife with diagrams and notes in the margins. Hopefully, Thaelin can read Orcish.", fua = "Важкенький. Фоліант рясніє схемами та нотатками на полях. Сподіваймося, Теелін уміє читати орочою." }
    t[107648] = { name = "Дистанційний Підривник", fen = "Not quite as elaborate as something the dwarves and gnomes would create.", fua = "Не такий вигадливий, як те, що створили б дворфи чи ґноми." }
    t[107650] = { name = "Дар Тіньового Місяця", fen = "An offering of totems and ornaments intended to quiet the ancestors of the Shadowmoon Clan.", fua = "Дар із тотемів та оздоб, призначений вгамувати предків клану Тіньового Місяця." }
    t[107656] = { name = "Тривожний Ящик Каза", fen = "Air holes have been punched in the sides of this crate and it rattles as you lift it.", fua = "У боках цього ящика пробиті дірки для повітря, і він торохтить, коли ви його піднімаєте." }
    t[107659] = { name = "Крижаний Камінь", fen = "Useful to keep beverages cool. Rapidly melting.", fua = "Корисний, щоб тримати напої холодними. Швидко тане." }
    t[107663] = "Оґрський Перстень на Палець Ноги"
    t[107664] = { name = "Бомбезні Бластери Босолупа з Blizzcon", fen = "Congratulations on vanquishing a fearsome foe in the depths of the Bloodmaul Slag Mines! Time to celebrate!", fua = "Вітаємо з перемогою над грізним ворогом у глибинах Шлакових Копалень Кривавого Молота! Час святкувати!" }
    t[107694] = "Лунарфолльський Заїзд, рівень 2"
