    t[109557] = { name = "Сироватка Мутації", fen = "Use on Grulk to restore his mutant strength.", fua = "Застосуйте на Ґрулку, щоб повернути йому мутантську силу." }
    t[109558] = { name = "Трактат про Алхімію Дренору", fen = "An introduction to the secrets of the alchemy of Draenor.", fua = "Вступ до таємниць алхімії Дренору." }
    t[109574] = { name = "ГУММ-І", fen = "Normally too complicated for the common person, this particular mailbox has extra-large buttons and instructions on it.", fua = "Зазвичай надто складна для пересічної людини, ця особлива поштова скринька має надвеликі кнопки та інструкції." }
    t[109575] = { name = "Аук'наару", fen = "One of the three fragments of the Heart of Auchindoun.", fua = "Один із трьох уламків Серця Аучиндона." }
