    t[109577] = "Сад Трав, Рівень 2"
    t[109578] = "Рибальська Хижка"
    t[109584] = { name = "Послання Оґрів", fen = "Keystone that can complete Ogre archaeology artifacts with missing fragments.", fua = "Ключ, що дозволяє завершити археологічні артефакти Оґрів з відсутніми уламками." }
    t[109585] = { name = "Шифр Араккоа", fen = "Keystone that can complete Arakkoa archaeology artifacts with missing fragments.", fua = "Ключ, що дозволяє завершити археологічні артефакти Араккоа з відсутніми уламками." }
    t[109586] = { name = "Крихкий Картографічний Журнал", fen = "Teaches you Draenor Archaeology.", fua = "Навчає вас Археології Дренору." }
    t[109591] = { name = "Ключ від Підземелля", fen = "If there is a skull on the handle it must be a dungeon key.", fua = "Якщо на руків'ї череп, то це напевно ключ від підземелля." }
    t[109599] = { name = "Нейронний Глушник", fen = "Annoyances include Leap of Faith, threat redirecting abilities, and some gadgets like the Swapblaster.", fua = "До прикрощів належать Стрибок віри, здатності перенаправлення загрози та деякі пристрої на кшталт Бластера-обмінника." }
    t[109602] = { name = "Echo of Murmur [TEMP ITEM & SPELL]", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
