    t[110394] = { name = "Світна Скалка Душі", fen = "This thin crystal shard glows with a soft light.", fua = "Ця тонка кристалічна скалка сяє м'яким світлом." }
    t[110424] = { name = "Дикий Капелюх Сафарі", fen = "Huntin' pets is dangerous business.  Don't go out without your hat.", fua = "Полювання на улюбленців — справа небезпечна. Не виходь без свого капелюха." }
