    t[110904] = { name = "Клинок Блекрока", fen = "The weapon is beautifully shaped but covered in patches of rust.", fua = "Зброя має чудову форму, але вкрита плямами іржі." }
    t[110905] = { name = "Перехід Гроннолова Рокаша", fen = "The opportunistic Gronnstalker Rokash will only hunt with the winning side.", fua = "Пристосуванець Гроннолов Рокаш полюватиме лише на боці переможців." }
    t[110907] = { name = "Нотатки Залізного Дослідника", fen = "The notes of an Iron Horde explorer investigating reports of mysterious flowers throughout Draenor.", fua = "Нотатки дослідника Залізної Орди, що розслідує повідомлення про загадкові квіти по всьому Дренору." }
    t[110997] = { name = "Дарунок від Клану Тіньового Місяця", fen = "A note from Ner'zhul, addressed to Kargath.", fua = "Записка від Нер'зула, адресована Карґату." }
    t[111308] = { name = "Злиток Морозного Заліза", fen = "Probably need some well padded gloves to carry this.", fua = "Щоб нести його, мабуть, знадобляться добре підбиті рукавички." }
    t[111348] = { name = "Прадавня Кора", fen = "Lightweight, yet surprisingly difficult to separate from the sleeping ancients.", fua = "Легка, та напрочуд важко відділяється від сплячих прадавніх." }
    t[111349] = { name = "Трактат про Гірництво на Дреноре", fen = "Outlines the properties of the valueable minerals of Draenor and how to mine them.", fua = "Описує властивості цінних мінералів Дренора і способи їх видобутку." }
    t[111350] = { name = "Збірник Трав Дренора", fen = "An overview of the magical herbs of Draenor and how to harvest them.", fua = "Огляд магічних трав Дренора і способів їх збирання." }
    t[111351] = { name = "Посібник з Білування на Дреноре", fen = "How to skin the beasts of Draenor.", fua = "Як білувати звірів Дренора." }
    t[111356] = { name = "Посібник з Риболовлі на Дреноре", fen = "Outlines the fish of Draenor and how to catch them.", fua = "Описує риб Дренора і способи їх упіймати." }
    t[111357] = { name = "Свисток Мортирника", fen = "A small bomb is etched on the back end.", fua = "На задньому кінці вигравіювано маленьку бомбу." }
    t[111364] = { name = "Перша Допомога на Дреноре", fen = "The methods in this book are outdated.", fua = "Методи в цій книзі застаріли." }
    t[111387] = { name = "Радощі Кулінарії Дренору", fen = "Teaches you Draenor Cooking and some basic recipes.", fua = "Навчає тебе Кулінарії Дренору та кількох базових рецептів." }
    t[111403] = { name = "Кітел Алхіміка", fen = "The bubling brew inside contains Metamorphic Crystals and Alchemical Catalysts. Occasionally, however, things may go horribly wrong.", fua = "Булькітливе вариво всередині містить метаморфічні кристали та алхімічні каталізатори. Утім, час від часу все може піти жахливо не так." }
    t[111406] = { name = "Sack of Draenor Ore (TEMP)", fen = "Standing in for sources of ore that aren't in yet.", fua = "Standing in for sources of ore that aren't in yet." }
