    t[122139] = { name = "Бинти Першої Допомоги", fen = "Used to heal wounded garrison soldiers at The Iron Front.", fua = "Використовуються для зцілення поранених солдатів гарнізону на Залізному Фронті." }
    t[122157] = { name = "Посох Вічності", fen = "Used by Archmage Rhonin at the conclusion of the Nexus War to link Dalaran to the Eye of Eternity so the city would become the new central nexus of magical energy.", fua = "Використаний архімагом Роніном наприкінці Війни Нексуса, щоб з'єднати Даларан з Оком Вічності, аби місто стало новим центральним нексусом магічної енергії." }
    t[122158] = { name = "Бузкове Серце", fen = "Jaina Proudmoore took this unassuming crystal and used it to flow magical energy throughout the city of Dalaran for all to enjoy.", fua = "Джайна Праудмур узяла цей непримітний кристал і використала його, щоб магічна енергія текла по всьому місту Даларан на втіху всім." }
    t[122159] = { name = "Око Антонідаса", fen = "Divined by Archmage Antonidas to guide ley lines to Dalaran's heart so the Kirin Tor were forever aware of magic's use anywhere in Azeroth.", fua = "Передбачене архімагом Антонідасом, щоб скеровувати лей-лінії до серця Даларану, аби Кірін-Тор навіки знали про будь-яке застосування магії будь-де в Азероті." }
    t[122163] = "Ящик Здобичі Розбитого Загарбника"
    t[122190] = { name = "Запрошення на Кільце Крові", fen = "It's leaking what is hopefully not real blood.", fua = "З нього сочиться щось, що, сподіваємось, не є справжньою кров'ю." }
    t[122191] = { name = "Закривавлена Стіпка Запрошень", fen = "Contains three invitations to the Ring of Blood in Nagrand.", fua = "Містить три запрошення на Кільце Крові в Награнді." }
