    t[138202] = { name = "Іскропоні XL", fen = "Attach fireworks to my horse? Why that sounds like a great idea!", fua = "Причепити феєрверки до мого коня? Та це ж чудова ідея!" }
    t[138231] = { name = "Бойовий Володар Ґаардун", fen = "Battlelord Gaardoun will arrive at the Fel Hammer and you will gain the ability to recruit Ashtongue Warriors who can accompany your Champions on missions", fua = "Бойовий Володар Ґаардун прибуде до Скверномолота, і ви отримаєте змогу набирати воїнів Попелястих Язиків, які зможуть супроводжувати ваших звитяжців у завданнях." }
    t[138232] = { name = "Лорамус Таліпедес", fen = "Loramus Thalipedes will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.", fua = "Лорамус Таліпедес прибуде до вашої Зали ордену й надасть вам змогу проводити дослідження у Дереві розвитку ордену." }
    t[138238] = { name = "Крабова Олія", fen = "Sure, why not?", fua = "Звісно, чому б ні?" }
    t[138239] = { name = "Цілий Крабовий Панцир", fen = "Maybe a bowl? Does he want a bowl?", fua = "Може, миска? Він хоче миску?" }
    t[138240] = { name = "Клацлива Крабова Клешня", fen = "At this point, you'll try anything.", fua = "На цьому етапі ви спробуєте будь-що." }
    t[138241] = { name = "Дрібний Пісок", fen = "Smooth, uniform sand shaken out from the shell.", fua = "Гладенький, однорідний пісок, витрушений із панцира." }
    t[138252] = { name = "Літописиця Елріанна", fen = "Chronicler Elrianne will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.", fua = "Літописиця Елріанна прибуде до вашої Зали ордену й надасть вам змогу проводити дослідження у Дереві розвитку ордену." }
    t[138253] = { name = "Наживка на Леїчерва", fen = "A gooey mass comprised mostly of leyworm entrails.", fua = "Липка маса, що складається переважно з нутрощів леїчерва." }
    t[138258] = { name = "Повід Давно Забутого Гіпогрифа", fen = "Teaches you how to summon this mount.  This is a flying mount.", fua = "Навчає вас прикликати це їздове створіння. Це летюче їздове створіння." }
