    t[138294] = { name = "Морський Бриз", fen = "A Challiane favorite that is a crisp yet creamy white with a hint of chewy tannins.", fua = "Улюблене вино Шалліани — свіже, та водночас оксамитове біле з натяком на терпкі таніни." }
    t[138295] = { name = "Королівське Червоне Фарондіса", fen = "Commisioned by the Farondis family, this Challiane special run is a complex and intellectually satisfying red wine.", fua = "Замовлене родиною Фарондіс, це особливе вино Шалліани — складне й вишукане червоне, що тішить розум." }
    t[138297] = { name = "Осердя Прадавньої Магії", fen = "A core of energy woven from ancient elven magic.", fua = "Осердя енергії, виткане з прадавньої ельфійської магії." }
    t[138300] = { name = "Багаж Божевільного", fen = "A mysterious container that is far larger on the inside than it has any right to be.", fua = "Загадкова скриня, що зсередини значно більша, ніж їй належить бути." }
