    t[138849] = { name = "Демонічний Журнал про Тал'кіеля", fen = "Contains the latest reports on Thal'kiel, the Skull of the Manari.", fua = "Містить найновіші звіти про Тал'кіеля, Череп Ман'арі." }
    t[138866] = { name = "Добре Загорнутий Пакунок", fen = "A fine sifting of moth dust swirls around it.", fua = "Навколо нього кружляє тонкий серпанок молевого пилу." }
    t[138872] = { name = "Закликачі Чорного Врожаю", fen = "A powerful troop which can accompany followers on missions to increase success chance.", fua = "Могутній загін, що може супроводжувати посіпак у завданнях, аби підвищити шанс на успіх." }
    t[138874] = { name = "Тріскотливі Скалки", fen = "Doesn't mix with Kaja Cola.", fua = "Не змішується з Каджа-Колою." }
    t[138883] = "Викликана Закуска Меріла"
    t[138892] = { name = "Королівська Печатка Принца Фарондіса", fen = "May they someday understand why I did what I did.", fua = "Нехай вони одного дня зрозуміють, чому я вчинив так, як вчинив." }
    t[138893] = { name = "Остання Мідяна Монета Рунаса", fen = "I wish I had some mana right... now! NOW! Now.", fua = "Хотів би я мати трохи мани просто... зараз! ЗАРАЗ! Зараз." }
    t[138894] = { name = "Срібна Монета Стеллагози", fen = "Please, protect my grandfather.", fua = "Прошу, захистіть мого дідуся." }
    t[138895] = { name = "Прадавня Монета Сенеґоса", fen = "Please, help my granddaughter lighten up a bit.", fua = "Прошу, допоможіть моїй онуці трохи повеселішати." }
    t[138896] = { name = "Дублон Окуни Довгоіклого", fen = "The adventure has been formidable, but I am far from my Moa'ki. I wish to soon see home.", fua = "Пригода була грандіозна, та я далеко від свого Моа'кі. Хочу скоріше побачити дім." }
    t[138897] = { name = "Дукат Укера", fen = "What the ookin' jeek? What kind o' mank-dookin' wicket-lover throws away perfectly good coin?!", fua = "Що за укінська чортівня? Який це манк-дукінський любитель хвірток викидає цілком гарну монету?!" }
    t[138898] = { name = "Монета Ґолка Гуркотуна", fen = "Golk wish Golk could fit out of this cave.", fua = "Ґолк хотів би, щоб Ґолк проліз із цієї печери." }
    t[138899] = { name = "Пекельна Мідна Монета Даглопа", fen = "I wish I were a little bit taller.", fua = "Хотів би я бути трішки вищим." }
    t[138900] = { name = "Знаменитий Ковбасний Капелюх Ґравіла Золотокосого", fen = "You never sausage a hat!", fua = "Ковбасу на голову не вдягають!" }
    t[138901] = { name = "Монета Тіранди", fen = "That I might protect those I hold dear, and continue to reflect the grace and light of Elune.", fua = "Щоб я могла захищати тих, хто мені дорогий, і далі відбивати ласку й світло Елуни." }
    t[138902] = { name = "Монета Малфуріона", fen = "Were we too late to stop the Nightmare?", fua = "Чи не запізно ми спинили Жахіття?" }
    t[138903] = { name = "Примарна Монета Кур'талоса Воронячого Гребеня", fen = "Perhaps if we curb these endless tides of demons, then some color may return to the world.", fua = "Можливо, якщо ми стримаємо ці нескінченні припливи демонів, до світу повернеться трохи барв." }
    t[138904] = { name = "Монета Джарода Шедоусонга", fen = "Give my troops the strength to overcome the trials of this land.", fua = "Дай моїм воякам силу подолати випробування цієї землі." }
    t[138905] = { name = "Кишенькові Гроші Пенелопи Гітроу", fen = "I kinda wish I was a worgen. Wouldn't that be the coolest?", fua = "Якось мені хочеться бути воргеном. Хіба це не було б найкрутіше?" }
    t[138906] = { name = "Сигіл Ремулоса", fen = "I give my thanks to the Cenarion Circle. May the mortal druids continue to prove themselves worthy of my father's name.", fua = "Я дякую Колу Кенарія. Нехай смертні друїди й надалі доводять, що гідні імені мого батька." }
    t[138907] = { name = "Золотий Листок Елотіра", fen = "Hmm... no coins. I wonder if this will suffice?", fua = "Гм... жодних монет. Цікаво, чи цього вистачить?" }
    t[138908] = { name = "Сигіл Коди", fen = "I suppose I might fancy a smackerel of honey.", fua = "Гадаю, я б не відмовився від ложечки меду." }
    t[138909] = { name = "Монета Короля Мрґл-Мрґла", fen = "Some days, I think the murlocs don't appreciate everything I do for them.", fua = "Іноді мені здається, що мурлоки не цінують усього, що я для них роблю." }
    t[138910] = { name = "Куля Гемета Несінгварі", fen = "I wish my son would hurry up and have kids already! Also, I want to shoot a moose.", fua = "Хотів би я, щоб мій син уже поквапився й завів дітей! А ще я хочу підстрелити лося." }
    t[138911] = { name = "Монета Маркі", fen = "Mrr glrrrgl mrr glrrgl glrr.", fua = "Мрр глррргл мрр глррґл глрр." }
    t[138912] = { name = "Монета Духоброда Чорнорога", fen = "For all the brothers and sisters I've lost.", fua = "За всіх братів і сестер, яких я втратив." }
    t[138913] = { name = "Монета Едді Шипобагнюки", fen = "Ooh, ooh! I hope I get to shoot a really cool gun! BLAM!", fua = "О-о, о-о! Сподіваюся, я зможу стрельнути з якоїсь дійсно крутої рушниці! БАБАХ!" }
    t[138914] = { name = "Монета Бумбума Бруллінгсворта", fen = "Come on, move that shell, Zoom! Just like we practiced!", fua = "Ну ж бо, рухай тим панциром, Зуме! Точно як ми тренувалися!" }
    t[138915] = { name = "Свічкова Монета Свічкового Короля", fen = "Me want find candlequeen! Hmm... maybe Jackie interested? Me give her candle, see what happens from there.", fua = "Я хотіти знайти свічкову королеву! Гм... може, Джекі цікаво? Я дати їй свічку, далі побачити, що буде." }
    t[138916] = { name = "Монета Торока Кривавого Тотему", fen = "I hate everything. Everything is horrible.", fua = "Я ненавиджу все. Усе жахливе." }
    t[138917] = { name = "Сквернозаплямована Монета Бога-Короля Сковальда", fen = "Strength. Glory. Power.", fua = "Сила. Слава. Могутність." }
    t[138918] = { name = "Монета Ґенна Сивогрива", fen = "A single shared goal does not erase the atrocities committed by the Forsaken.", fua = "Одна спільна мета не стирає звірств, скоєних Відступниками." }
    t[138919] = { name = "Монета Натаноса Чумокликача", fen = "Dark Lady watch over this fountain.", fua = "Нехай Темна Володарка пильнує цей фонтан." }
    t[138920] = { name = "Монета Гельї", fen = "If found, please return this coin to me... in person.", fua = "Якщо знайдете, поверніть цю монету мені... особисто." }
    t[138921] = { name = "Монета Сера Фінлі Мрргглтона", fen = "Good heavens, is this a wishing well?  How quaint.", fua = "Святі небеса, невже це фонтан бажань? Як мило." }
    t[138922] = { name = "Монета Гаві", fen = "Ughh... this meat is so dry. I wish I had some gravy.", fua = "Ох... це м'ясо таке сухе. Хотіла б я мати трохи підливи." }
    t[138923] = { name = "Дерев'яний Гріш Видгара", fen = "Talking to adventurers is so tiring... a few decades of peace is all I ask...", fua = "Розмовляти з шукачами пригод так стомливо... Кілька десятиліть спокою — це все, чого я прошу..." }
    t[138924] = { name = "Позолочена Мідна Монета Ракса Шестизарядного", fen = "Fooled ya, ya dumb fountain.", fua = "Обдурив тебе, дурний фонтане." }
    t[138925] = { name = "Монета Першої Арканістки Талісри", fen = "May the downtrodden one day rise up and take the place of those that would oppress them.", fua = "Нехай пригноблені одного дня повстануть і посядуть місце тих, хто їх гнобив." }
    t[138926] = { name = "Монета Магістрикс Елісанди", fen = "I wish to protect my people from the vile outsiders that wish to harm them. Whatever it takes.", fua = "Я бажаю захистити свій народ від мерзенних чужинців, які прагнуть йому зашкодити. Хай там що." }
    t[138927] = { name = "Зникома Монета Окулета", fen = "Oh, to have an apprentice that could keep up with me!", fua = "Ах, мати б учня, який міг би за мною встигати!" }
    t[138928] = { name = "Родинний Герб Лай'лет Лунастре", fen = "I wish my father were alive, to help guide us through these difficult times.", fua = "Хотіла б я, щоб мій батько був живий і допоміг нам пройти крізь ці важкі часи." }
    t[138929] = { name = "Мокра Монета Перлолова Фіна", fen = "Gloooglrr mrm.", fua = "Глооґлрр мрм." }
    t[138930] = { name = "Монета Радника Вандроса", fen = "Keep your wishes for yourself. I do not negotiate with fountains.", fua = "Залиш свої бажання при собі. Я не веду перемовин із фонтанами." }
    t[138931] = { name = "Монета Ґул'дана", fen = "I just want all worlds to burn.", fua = "Я лише хочу, щоб усі світи згоріли." }
    t[138932] = { name = "Знак Йоулона", fen = "I want more kitties.", fua = "Я хочу більше котиків." }
    t[138933] = { name = "Монета Аллари Душеїдки", fen = "Fish do not have souls. This is pointless.", fua = "Риби не мають душ. Це безглуздо." }
    t[138934] = { name = "Монета Альтруїса Стражденного", fen = "Think for yourself.", fua = "Думай своєю головою." }
    t[138935] = { name = "Монета Сіани Нічної Глефи", fen = "I wish I was stronger.", fua = "Хотіла б я бути сильнішою." }
    t[138936] = { name = "Монета Фалари Нічноспівної", fen = "I remember when Suramar was beautiful and tranquil... before Azshara and her Highborne ruined everything. Wishes will buy you nothing except regret.", fua = "Я пам'ятаю, коли Сурамар був прекрасним і спокійним... перш ніж Азшара та її Високонароджені все зруйнували. Бажання не принесуть тобі нічого, крім жалю." }
    t[138937] = { name = "Монета Ізал Білолунної", fen = "These magi allowed me to land here. While most do nothing but eye you with suspicion and contempt, or worse, some still see past the surface. My wish is for all of us to work together and recognize our true enemy: the Burning Legion.", fua = "Ці маги дозволили мені тут оселитися. Хоча більшість лише дивиться на тебе з підозрою й зневагою, а то й гірше, дехто все ж бачить за зовнішністю. Моє бажання — щоб ми всі діяли разом і визнали свого справжнього ворога: Палаючий Легіон." }
    t[138938] = { name = "Монета Джейса Дарквівера", fen = "In my previous life, I would have loved to have lived in this floating marvel. I would have spent the days fishing in this magic fountain in-between practicing the arcane arts. Those days are long gone.", fua = "У минулому житті я залюбки оселився б у цьому летючому диві. Я проводив би дні, рибалячи в цьому чарівному фонтані між заняттями таємним мистецтвом. Ті дні давно минули." }
    t[138939] = { name = "Монета Кейна Сонцелютого", fen = "Strong leadership and a clear vision are the only path to victory.", fua = "Сильне керівництво й чітке бачення — єдиний шлях до перемоги." }
    t[138940] = { name = "Монета Кор'вас Кривавошип", fen = "I don't have the luxury of fishing and wishing. There are demons to kill.", fua = "Я не можу дозволити собі розкіш рибалити й загадувати бажання. Тут є демони, яких треба вбивати." }
    t[138941] = { name = "Монета", fen = "Gain 1 Mana Crystal this turn only.", fua = "Отримайте 1 Кристал Мани лише цього ходу." }
    t[138942] = { name = "Ботмонета Блінгтрона", fen = "The wishing module is busy at this time. Please try again later. (Error 37)", fua = "Модуль бажань наразі зайнятий. Спробуйте пізніше. (Помилка 37)" }
    t[138943] = { name = "Монета Леді Ліадрін", fen = "May the Light bathe this land in all its glory.", fua = "Нехай Світло осяє цю землю в усій своїй величі." }
    t[138944] = { name = "Монета Лунари", fen = "What is nature's call? I actually do wish someone would finally tell me what \"nature's call\" is.", fua = "Що таке поклик природи? Я справді хотіла б, щоб хтось нарешті пояснив мені, що таке цей \"поклик природи\"." }
    t[138945] = { name = "Монета Іллідана", fen = "An end to the Burning Legion.", fua = "За кінець Палаючого Легіону." }
    t[138946] = { name = "Королівська Печатка Королеви Азшари", fen = "Soon, you will ALL feel my wrath!!!", fua = "Невдовзі ви ВСІ відчуєте мій гнів!!!" }
    t[138947] = { name = "Монета на Шнурку Ґаллівікса", fen = "Yes! This way I can get my wish AND keep my coin. Hah! Oh no, the string broke! Stupid fountain, give me my coin back...", fua = "Так! Тепер я і бажання загадаю, І монету збережу. Ха! О ні, шнурок порвався! Дурний фонтан, віддай мою монету..." }
    t[138948] = { name = "Монета Лі Лі", fen = "My wish is to never run out of newly-discovered continents to explore.", fua = "Моє бажання — щоб новознайдені континенти для дослідження ніколи не закінчувалися." }
    t[138955] = "Ілюзія: Руна Гострольоду"
    t[138965] = "Чарівна Паличка Висмоктування"
    t[138966] = { name = "Гірські Ягоди", fen = "Colorful fruit from the Highmountain region that emits a pungent aroma.", fua = "Барвистий плід із краю Високогір'я, що виділяє різкий аромат." }
    t[138967] = "Велика Золота Рибка З Фонтана"
    t[138972] = { name = "Чорничне Варення", fen = "The container contains mushed berries covered in a 'green' protective layer.", fua = "У посудині розчавлені ягоди, вкриті \"зеленим\" захисним шаром." }
    t[138973] = { name = "Гострий і Запліснявілий Ґамалуст", fen = "It's commonly held that the green parts protect it. Just make sure you don't eat those parts.", fua = "Заведено вважати, що зелені частини його захищають. Тільки гляди не з'їж саме ці частини." }
    t[138974] = { name = "Обвуглений Старорог", fen = "Burned beyond recognition so as not to remind of what it once was.", fua = "Спалений до невпізнанності, щоб не нагадувати, чим він колись був." }
    t[138975] = { name = "Талі Води Високогір'я", fen = "Pristine the day it was collected, though that day may have been some time ago...", fua = "Бездоганно чисті того дня, коли їх зібрали, хоча той день, мабуть, був уже доволі давно..." }
    t[138976] = { name = "Черствий Рисовий Корж із Громового Тотему", fen = "Listed as past due, the Prepfoots got a killer deal. These cakes never seem to go bad though.", fua = "Хоча термін придатності минув, Пугачолапи відхопили чудову оборудку. Утім, ці коржі, схоже, ніколи не псуються." }
    t[138977] = "Рисовий Корж Громототема"
    t[138992] = { name = "Медаль Звитяги Великого Маршала", fen = "A prestigious commendation reserved for the most valiant heroes of the Alliance.", fua = "Почесна відзнака, призначена лише для найвідважніших героїв Альянсу." }
    t[138996] = { name = "Медаль Звитяги Верховного Воєначальника", fen = "A prestigious commendation reserved for the greatest heroes of the Horde.", fua = "Почесна відзнака, призначена лише для найвеличніших героїв Орди." }
    t[138997] = { name = "Яйце Ґаята", fen = "Hard as a... rock.", fua = "Тверде, мов... камінь." }
    t[138998] = "Карта Ліній Сили"
    t[139001] = { name = "Вербувальник [RECRUITER A]", fen = "Recruiter A will arrive in the Dalaran Sewers and you will gain the ability to recruit [TROOP A].", fua = "Вербувальник A прибуде до Каналізації Даларану, і ви здобудете змогу набирати [TROOP A]." }
    t[139003] = { name = "Зламаний Портал для Улюбленців", fen = "This item appears to no longer function.", fua = "Схоже, цей предмет більше не діє." }
