    t[139028] = "Диск Звіздаря"
    t[139032] = { name = "Джерельна Вода Фрейї", fen = "The water is so clear that the bottle almost looks empty.", fua = "Вода така прозора, що пляшка здається майже порожньою." }
    t[139034] = { name = "Лист від Ґул'дана", fen = "A glowing scroll written by the hand of chaos.", fua = "Осяйний сувій, написаний рукою хаосу." }
    t[139038] = { name = "Вищі Елементалі", fen = "A powerful troop which can accompany followers on missions to increase success chance.", fua = "Могутній загін, що може супроводжувати посіпак у завданнях, аби підвищити шанс на успіх." }
