    t[139043] = { name = "Сльоза Елуни", fen = "This titan relic pulses with energy.", fua = "Ця реліквія титанів пульсує енергією." }
    t[139044] = { name = "Торбинка з Буями", fen = "A satchel filled with leystone buoys.", fua = "Торбинка, наповнена буями з лейстоуну." }
    t[139046] = { name = "Демонічний Журнал про Скіпетр", fen = "Contains the latest reports on the Scepter of Sargeras", fua = "Містить найновіші відомості про Скіпетр Саргераса." }
    t[139138] = { name = "Влучні Стрільці", fen = "A powerful troop which can accompany followers on missions to increase success chance.", fua = "Могутній загін, що може супроводжувати посіпак у завданнях, аби підвищити шанс на успіх." }
