    t[139140] = { name = "Вербувальниця Ленара", fen = "Recruiter Lenara will arrive in Trueshot Lodge and you will gain the ability to recruit Squads of Archers who can accompany your Champions on missions.", fua = "Вербувальниця Ленара прибуде до Хижі Влучного Пострілу, і ви здобудете змогу набирати Загони Лучників, що можуть супроводжувати ваших Чемпіонів у місіях." }
    t[139141] = { name = "Темний Закликач Марог", fen = "Dark Summoner Marogh will arrive in Acherus and you will gain the ability to raise Packs of Ghouls who can accompany your Champions on missions.", fua = "Темний Закликач Марог прибуде до Ахерусу, і ви здобудете змогу здіймати Зграї Упирів, що можуть супроводжувати ваших Чемпіонів у місіях." }
    t[139142] = { name = "Великий Анахорет Ґесслар", fen = "Grand Anchorite Gesslar will arrive in Netherlight Temple and you will gain the ability to recruit Groups of Acolytes who can accompany your Champions on missions.", fua = "Великий Анахорет Ґесслар прибуде до Храму Світла Порожнечі, і ви здобудете змогу набирати Гурти Послушників, що можуть супроводжувати ваших Чемпіонів у місіях." }
    t[139143] = { name = "Архіваріус Зубаші", fen = "Archivist Zubashi will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.", fua = "Архіваріус Зубаші прибуде до вашої Зали Ордену й дарує вам змогу проводити дослідження у Дереві Розвитку Ордену." }
    t[139144] = { name = "Архонт Торіас", fen = "Archon Torias will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.", fua = "Архонт Торіас прибуде до вашої Зали Ордену й дарує вам змогу проводити дослідження у Дереві Розвитку Ордену." }
