    t[139302] = { name = "Гравюра зі Скрижалі Воронового Ока", fen = "A partial story of the Raven's Eye creation myth and how it came to be in the hands of Lord Kur'talos Ravencrest.", fua = "Частина оповіді про міф створення Воронового Ока та про те, як воно потрапило до рук лорда Кур'талоса Воронячого Хребта." }
