    t[139400] = { name = "Прадавня Магія і Як Володіти Нею, Не Знищивши Світ", fen = "A compendium of knowledge accumulated from many great Archmages of the Kirin Tor, with thorough retellings of the follies that have befallen reckless mages in times past.", fua = "Збірник знань, накопичених багатьма великими верховними магами Кірін-Тору, з докладними переказами безумств, що спіткали необачних магів у минулі часи." }
    t[139401] = { name = "Доля Еґвінн", fen = "The final recorded history of Archmage Aegwynn, Guardian of Tirisfal, as recounted by historian Llore.", fua = "Останній записаний літопис верховної магині Еґвінн, Хранительки Тірісфалу, у переказі історика Ллора." }
    t[139402] = { name = "Скверний Фоліант Воргалуса Дора", fen = "Demonic scrawlings of the departed warlock Vorgalus Dor, recounting many ancient and powerful weapons that originated on far away Legion worlds.", fua = "Демонічні записи покійного чорнокнижника Воргалуса Дора, що оповідають про багато прадавніх і могутніх видів зброї, які походять з далеких світів Легіону." }
    t[139403] = { name = "Могутні Магічні Фокуси та Їхні Власники", fen = "A thorough recounting of magical artifacts and weapons throughout history, researched and written by Archmage Karlain.", fua = "Докладна оповідь про магічні артефакти та зброю крізь усю історію, досліджена й написана архімагом Карлейном." }
    t[139409] = { name = "Лист від Мандрівників у Часі", fen = "It is addressed to you using beautiful calligraphy.", fua = "Адресований вам вишуканою каліграфією." }
