    t[139513] = { name = "Рукописне Запрошення", fen = "Written in gently glowing ink. The parchment smells subtly of flowers.", fua = "Написане ледь сяйливим чорнилом. Пергамент ледь чутно пахне квітами." }
    t[139520] = { name = "Гарячкове Благання", fen = "Not entirely incoherent, but clearly written by someone suffering from a high temperature.", fua = "Не зовсім беззв'язне, та вочевидь написане кимось у сильній гарячці." }
    t[139521] = { name = "Обпалена Записка", fen = "The edges seem burned by fel magic. A message is scribbled in the center.", fua = "Краї, схоже, обпалені скверномагією. У центрі нашкрябано послання." }
