    t[139536] = { name = "Еманація Вітрів", fen = "Secrets of the elemental power held within the famed blade of Thunderaan the Windlord.", fua = "Таємниці елементарної сили, що криються у славетному клинку Тандераана Володаря Вітрів." }
    t[139540] = { name = "Сторінка Щоденника Апоні", fen = "Written hastily.", fua = "Написана поспіхом." }
    t[139541] = { name = "Сигіл Командування", fen = "It glows in the presence of the Legion portal.", fua = "Світиться поблизу порталу Легіону." }
    t[139542] = { name = "Шмат Парусини", fen = "You doubt even a tailor could use this.", fua = "Ви сумніваєтеся, що навіть кравець знайшов би цьому застосування." }
    t[139543] = { name = "Зламаний Румпель", fen = "It could be salvaged by a talented shipwright.", fua = "Талановитий корабельник міг би його полагодити." }
    t[139544] = { name = "Зотлілий Бойовий Стяг Хвилерогів", fen = "Once flown proudly on the masts of vrykul longships.", fua = "Колись гордо майорів на щоглах врайкульських драккарів." }
    t[139545] = { name = "Іржавий Корабельний Дзвін", fen = "Used to signal other ships though dense fog.", fua = "Використовувався, щоб подавати сигнали іншим кораблям крізь густий туман." }
    t[139546] = { name = "Звивна Аніма Душ", fen = "A failed experiment in magically stealing the power from the long dead.  The resulting mass twists and undulates unsettlingly.", fua = "Невдалий експеримент із магічного викрадення сили в давно померлих. Утворена маса тривожно звивається й хвилюється." }
    t[139547] = { name = "Руни Затемнення", fen = "Written in an ancient language that no living soul remembers, yet somehow the words leap to your tongue, yearning to be read.", fua = "Написані прадавньою мовою, якої не пам'ятає жодна жива душа, та якимось чином слова самі зриваються з язика, прагнучи бути прочитаними." }
    t[139548] = { name = "Гак Кістколома", fen = "Fed by the steady settling energy of Icecrown Citadel, this crude and brutal weapon could easily be fashioned into an instrument of death.", fua = "Живлена сталим осідаючим потоком енергії Цитаделі Крижаної Корони, ця груба й жорстока зброя легко могла б стати знаряддям смерті." }
    t[139549] = { name = "Личина Смертоблуда", fen = "A dark weapon from a long dead master, hungering to taste blood again.", fua = "Темна зброя давно померлого майстра, що прагне знову скуштувати крові." }
    t[139550] = { name = "Оплот Залізного Вартового", fen = "Once an indomitable construct of the draenei, turned by the Legion into an instrument of destruction, the Iron Warden fell long ago during the taking of the Aldrachi homeworld.", fua = "Колись непохитний конструкт дренеїв, перетворений Легіоном на знаряддя руйнації, Залізний Вартовий упав давним-давно під час захоплення рідного світу алдрахі." }
    t[139551] = { name = "Сонячний Квіт", fen = "A rare flower from the Emerald Dream, not seen in Azeroth since the War of the Ancients.", fua = "Рідкісна квітка зі Смарагдового Сну, якої не бачили в Азероті від часів Війни Прадавніх." }
    t[139552] = { name = "Перо Місячного Духа", fen = "A single feather from a reclusive wild god. With it, a Druid of the Claw could learn to master a previously unseen form.", fua = "Єдине перо потаємного дикого бога. З ним друїд Пазура міг би навчитися опанувати небачену досі подобу." }
    t[139553] = { name = "Знак Стража Галявини", fen = "A powerful mark put on wild bears by Ursol to empower them as defenders of the wilds in times of need.", fua = "Могутній знак, накладений на диких ведмедів Урсолом, щоб наділити їх силою захисників хащ у часи скрути." }
    t[139554] = { name = "Жолудь Нескінченного", fen = "Several of these magical acorns were saved from one of the oldest trees in the dream before it fell to the Nightmare.", fua = "Кілька цих магічних жолудів врятували з одного з найдавніших дерев Сну, перш ніж воно впало перед Жахіттям." }
    t[139557] = { name = "Останній Подих Лісу", fen = "Ursoc sacrificed his life for the wilds twice, but he leaves behind a legacy for other noble defenders to uphold in his absence.", fua = "Урсок двічі віддав життя за хащі, та лишив у спадок взірець, який інші шляхетні захисники мають берегти за його відсутності." }
    t[139558] = { name = "Ноша Вовномага", fen = "Cote \"Shepherd\" Metcalf was unable to unlock the secrets of this mysterious bleating staff.", fua = "Коут «Пастух» Меткалф не зміг розгадати таємниці цього загадкового бекаючого посоха." }
    t[139559] = { name = "Задум Зірок", fen = "Nightborn designs for a spellblade mirroring a treasured constellation of their people.", fua = "Креслення нічнонароджених для чароклинка на честь сузір'я, яке вшановує їхній народ." }
    t[139560] = { name = "Вічногорючий Кристал", fen = "A frozen crystal lit with an everlasting heatless fire. Safe to touch, it shows no signs of melting.", fua = "Замерзлий кристал, осяяний вічним вогнем без тепла. Його безпечно торкатися, і він не виявляє жодних ознак танення." }
    t[139561] = { name = "Легенда Мавпячого Короля", fen = "A very potent and special brew, said to have been concocted by the Monkey King himself. The keg is exquisite, and might serve other purposes beyond housing brew...", fua = "Вельми міцний і особливий трунок, що, як кажуть, його зварив сам Мавпячий Король. Барило вишукане і могло б служити не лише для зберігання трунку..." }
    t[139562] = { name = "Подих Невмирущого Змія", fen = "A swirling font of magical energy, said to originate from the belly of a dragon older than time.", fua = "Вирове джерело магічної енергії, що, як кажуть, походить із черева дракона, старшого за сам час." }
    t[139563] = { name = "Грозовий Кулак", fen = "Little is known about the creation of the Stormfist, but the power within it seems to originate from both Therazane and Al'Akir, a very unexpected union.", fua = "Про створення Грозового Кулака відомо мало, та сила в ньому, схоже, походить водночас від Теразани й Ал'Акіра — вельми несподіване поєднання." }
    t[139564] = { name = "Загублені Едикти Вартового", fen = "We have sworn to restore hope to this troubled world.  To seek out tyranny and evil wherever they take root... and bring the hammer of justice down upon the wicked.", fua = "Ми поклялися повернути надію цьому стражденному світу. Вистежувати тиранію і зло, де б вони не вкорінилися... і опускати молот правосуддя на нечестивих." }
    t[139565] = { name = "Іскра Полеглого Екзарха", fen = "When Exarch Kelios fell, the remaining hope of holding the temple faded away. The Legion had won. The only peace they would find now was in the thought of those few who had escaped, but the Legion would soon take that from them as well.", fua = "Коли впав екзарх Келіос, згасла й остання надія втримати храм. Легіон переміг. Єдиний спокій, який вони ще могли знайти, був у думці про тих небагатьох, хто врятувався, але невдовзі Легіон відбере й це." }
    t[139566] = { name = "Серце Скверни", fen = "A grim glimpse at a past that Ashbringer left behind, that many hoped it would never rekindle.", fua = "Похмурий зблиск минулого, яке полишив Згубник Скверни і яке багато хто сподівався ніколи не оживити знову." }
    t[139567] = { name = "Письмена Кінця", fen = "Words gathered from the scattered tomes of the Archivist, predicting dire times to come.", fua = "Слова, зібрані з розпорошених фоліантів Архіваріуса, що віщують лихі часи попереду." }
    t[139568] = { name = "Посох Світлороджених", fen = "The staff rings peacefully with the power of the Valkyra.  The sound comes to rest when touched.", fua = "Посох мирно дзвенить силою Валькір. Звук стихає від дотику." }
    t[139569] = { name = "Пазур Н'Зота", fen = "Eyes blinking. Flesh pulsing. It is very much still alive.", fua = "Очі кліпають. Плоть пульсує. Воно безперечно ще живе." }
    t[139570] = { name = "Шифр Зламаної Кістки", fen = "Secrets of a long-dead assassin known only as \"The Bonebreaker.\" It's rumored that she took up the habit of breaking the leg bones of her slain victims after one of them came back from the dead to seek revenge.", fua = "Таємниці давно померлої вбивці, відомої лише як «Костоломка». Подейкують, що вона взяла за звичку ламати кістки ніг своїм убитим жертвам після того, як одна з них повернулася з того світу, щоб помститися." }
    t[139571] = { name = "Фоліант Потойбічних Отрут", fen = "A text passed down through generations of Zandalari Shadowhunters, detailing some of the more exotic weapons and venoms they used to slay their enemies.", fua = "Текст, переданий через покоління тіньових мисливців Зандаларі, з описом найбільш незвичних видів зброї та отрут, якими вони вбивали ворогів." }
    t[139572] = { name = "Загублений Кодекс Амані", fen = "A long-lost troll text focused on many of the leaders that have risen and fallen over the generations. It spends a particularly long time focusing on a troll named Atai'natha and a powerful magical claw he used to enforce his rule.", fua = "Давно загублений тролський текст, присвячений багатьом вождям, що поставали й падали впродовж поколінь. Особливо багато уваги в ньому приділено тролеві на ім'я Атай'ната і могутньому магічному пазурові, яким він тримав владу." }
    t[139573] = { name = "Бойова Булава Ширвалли", fen = "Despite its ornate frame, this brutal mace claimed many lives in an unbidden attempt to honor the primal god Shirvallah. Long ago, it was lost to the sea with the high priest who wielded it.", fua = "Попри пишне оздоблення, ця жорстока булава забрала чимало життів у нав'язаному прагненні вшанувати первинного бога Ширваллу. Давним-давно її поглинуло море разом із верховним жерцем, що нею володів." }
    t[139574] = { name = "Кільце Потонулої Королеви", fen = "Slithering beneath the waves, the Highborne resembled nothing of their previous selves. They were one with the depths now, and servants of something darker beneath...", fua = "Звиваючись під хвилями, високороджені не нагадували й сліду колишніх себе. Тепер вони були єдині з глибинами і служили чомусь темнішому, що чаїлося внизу..." }
    t[139575] = { name = "Сутність Катеси", fen = "Distilled from the skulls of great champions, this essence offers great power to those willing to pay the dark cost.", fua = "Виготовлена з черепів великих звитяжців, ця сутність дарує велику силу тим, хто готовий заплатити темну ціну." }
    t[139576] = { name = "Лик Першого Пробудника", fen = "Among the most prominent phrenologists during this period were Thal'kiel and Archimonde. Thal'kiel in particular was noted for having the archetypal sorcerer's skull, for which he was widely admired.", fua = "Серед найвідоміших френологів тієї доби були Тал'кіель і Архімонд. Тал'кіель особливо вирізнявся взірцевим черепом чародія, за що його широко вшановували." }
    t[139577] = { name = "Палаючий Самоцвіт Саргераса", fen = "A dark thirsting flame burns within the crimson jewel, lapping against the edges as you near.", fua = "У багряному самоцвіті палає темне спрагле полум'я, що лиже краї, коли ви наближаєтеся." }
    t[139578] = { name = "Арканітовий Клинколамач", fen = "Hand-crafted by Helgar, master smith of Skyhold, this axe should surpass any steel found on Azeroth.", fua = "Власноруч викуваний Гельгаром, майстром-ковалем Небесної Тверджі, цей топір має перевершити будь-яку сталь Азероту." }
    t[139579] = { name = "Драконоборці", fen = "Two fearsome axes bearing the skulls of slain dragons, built upon vrykul enchanted runewood. Impressive weaponry by any warrior's standards.", fua = "Дві грізні сокири з черепами вбитих драконів на руків'ях із зачарованого врайкулами рунодерева. Зброя, що вразить будь-якого воїна." }
    t[139580] = { name = "Палаючий Нагрудник Світоламача", fen = "Dark molten blood from Neltharion himself pours along its ridges, left smoldering in his former lair for countless years, waiting to be reunited with a lost scale from the same father.", fua = "Темна розплавлена кров самого Нелтаріона стікає по його гранях. Незліченні роки вона тліла в його колишньому лігві, чекаючи возз'єднання із загубленою лускою того ж батька." }
    t[139583] = { name = "Демонічна Руна", fen = "Indecipherable characters are engraved upon the stone.", fua = "На камені викарбувано незбагненні символи." }
    t[139593] = "Мішок Врятованих Товарів"
    t[139594] = "Ящик Утилю"
    t[139620] = { name = "Повний примірник «Посібника Ната Пейгла з екстремальної риболовлі»", fen = "Someone would be very interested in this.", fua = "Дехто був би вельми цим зацікавлений." }
    t[139623] = "Філактерія Тімолейна"
    t[139624] = { name = "Скалка Темряви", fen = "Dark smoke obscures the inside of the crystal, but faint screams can be heard from somewhere deep within.", fua = "Темний дим затьмарює нутрощі кристала, та з глибини десь усередині линуть ледь чутні крики." }
    t[139632] = "Крихітні Захисні Окуляри"
    t[139652] = { name = "Силомерехтлива Собача Риба", fen = "Notoriously shy and difficult to catch.", fua = "Сумнозвісно полохлива й важка для вилову." }
    t[139653] = { name = "Самітник Нар'таласу", fen = "These crabs spend their days hidden beneath the sands of Azsuna's rivers and lagoons.", fua = "Ці краби проводять дні, ховаючись під пісками річок і лагун Азсуни." }
    t[139654] = { name = "Примарна Риба-Королева", fen = "A spectre of the queenfish as they once were, ten thousand years ago.", fua = "Привид риби-королеви, якою вона була колись, десять тисяч років тому." }
    t[139655] = { name = "Жахоплавець", fen = "Succumbed to the nightmare that plagues Val'Sharah.", fua = "Піддався кошмару, що мучить Вал'шару." }
    t[139656] = { name = "Колючий Камбала", fen = "Covered with spines, from gill to tail.", fua = "Укрита шипами від зябер до хвоста." }
    t[139657] = { name = "Прадавня Моховійка", fen = "The moon-blessed waters of Val'sharah allow the mossgill to grow indefinitely.", fua = "Благословенні місяцем води Вал'шари дають моховійкам рости безмежно." }
    t[139658] = { name = "Гірська Риба-Куля", fen = "Revered by the murlocs of Highmountain.", fua = "Шанована мерлоками Високогір'я." }
    t[139659] = { name = "Холодноводний Короп", fen = "This breed detests warmth, preferring the icy waters of snowy Highmountain.", fua = "Ця порода ненавидить тепло, віддаючи перевагу крижаним водам засніженого Високогір'я." }
    t[139660] = { name = "Прадавній Лосось Високогір'я", fen = "With the drogbar hunting them so voraciously, Highmountain salmon rarely get this old.", fua = "Оскільки дроґбари полюють на них так жадібно, лосось Високогір'я рідко доживає до такого віку." }
    t[139661] = { name = "Уделфіск", fen = "The oodelfjisk were fished to extinction long ago.", fua = "Уделфісків давно виловили до повного зникнення." }
    t[139662] = { name = "Сірочеревий Омар", fen = "Attracted to anything shiny.", fua = "Його приваблює все блискуче." }
    t[139663] = { name = "Громовий Штормовий Скат", fen = "The largest stormrays are the most deadly.", fua = "Найбільші штормові скати — найсмертоносніші." }
    t[139664] = { name = "Жаба-Магоїд", fen = "Much like the nightborne, the frogs of Suramar have developed an insatiable appetite for magic.", fua = "Як і Нічнонароджені, жаби Сурамару виробили невгамовний апетит до магії." }
    t[139665] = { name = "Риба-Куля Провидця", fen = "On rare occasions, murlocs have been known to use these fish as weapons.", fua = "У рідкісних випадках мерлоки, як відомо, використовують цих риб як зброю." }
    t[139666] = { name = "Опоганений Рунолуский Коі", fen = "The skin of a fish but the heart of a demon. Even the fish are not safe from the Legion.", fua = "Шкіра риби, але серце демона. Навіть риби не убезпечені від Легіону." }
    t[139667] = { name = "Риба-Сокира", fen = "Similar to a swordfish, but with a slower attack speed.", fua = "Схожа на рибу-меч, але з повільнішою швидкістю атаки." }
    t[139668] = { name = "Глибоководний Кальмар", fen = "Cannot be fished, as they never come within a mile of the ocean's surface. These squid must be obtained through... alternative methods.", fua = "Його неможливо виловити, адже він ніколи не наближається до поверхні океану ближче ніж на кілометр. Цих кальмарів доводиться здобувати... іншими способами." }
    t[139669] = { name = "Прадавня Чорна Баракуда", fen = "Outside of the notorious whale shark, this is one of the largest fish in the seas of Azeroth.", fua = "Окрім сумнозвісної китової акули, це одна з найбільших риб у морях Азероту." }
    t[139771] = { name = "Вируюча Сутність", fen = "A horrific mass of corrupted essence, held together by volatile energy.", fua = "Жахлива маса зіпсованої сутності, утримувана докупи мінливою енергією." }
    t[139775] = { name = "Прихильник Альянсу", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[139776] = { name = "Фанатик Орди", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[139777] = { name = "Дивний Ящик", fen = "Do not return to sender.", fua = "Не повертати відправнику." }
    t[139778] = { name = "Щоденник Наталі", fen = "A collection of notes penned by the leader of the Cult of Forgotten Shadows.", fua = "Збірка нотаток, написаних рукою очільниці Культу Забутих Тіней." }
    t[139783] = { name = "Вивітрена Реліквія", fen = "Vaguely shaped like a skull, the major features have been worn down by the years.", fua = "Невиразно нагадує череп, головні риси якого стерлися з роками." }
    t[139789] = { name = "Трансмутант", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[139790] = { name = "Звільнений Драконеня", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[139791] = { name = "Кошеня-Сова в Засідці", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
