    t[139888] = "Виснажене Осердя Морозу"
    t[139892] = "Неактивна Демонічна Філактерія"
    t[139893] = { name = "Техніка Білування: Цілий Зуб", fen = "Teaches you how to gather Unbroken Teeth while skinning creatures of the Broken Isles.", fua = "Навчає вас, як збирати цілі зуби під час білування створінь Зламаних Островів." }
    t[139894] = { name = "Техніка Білування: Ціла Пазуриста Лапа", fen = "Teaches you how to gather Unbroken Claws while skinning creatures of the Broken Isles.", fua = "Навчає вас, як збирати цілі пазуристі лапи під час білування створінь Зламаних Островів." }
    t[139895] = { name = "Техніка Білування: Різництво Легіону", fen = "Teaches you how to gather meat while skinning creatures of the Broken Isles.", fua = "Навчає вас, як збирати м'ясо під час білування створінь Зламаних Островів." }
    t[139896] = { name = "Техніка Білування: Потрошіння Легіону", fen = "Teaches you how to gather Oddly-Shaped Stomachs while skinning creatures of the Broken Isles.", fua = "Навчає вас, як збирати дивно сформовані шлунки під час білування створінь Зламаних Островів." }
    t[140038] = "Запилений Фокусувальний Кристал"
    t[140090] = { name = "Що Було Першим — Дерево чи Зерно?", fen = "An exploration of the origins of life on Azeroth, by Archdruid Vorenthias.", fua = "Дослідження походження життя на Азероті, від верховного друїда Воренціаса." }
    t[140091] = { name = "Таємниці Диких Богів", fen = "Accounts and sightings of the numerous wild gods of Azeroth, spanning thousands of years of accumulated history.", fua = "Свідчення та спостереження численних диких богів Азероту, що охоплюють тисячі років зібраної історії." }
    t[140092] = { name = "Друїди Зграї", fen = "A cautionary tale of pride and hubris, and of the many dangers of shapeshifting.", fua = "Повчальна оповідь про гордість і пиху та про численні небезпеки перевтілення." }
    t[140093] = { name = "Нерозказані Оповіді Війни Прадавніх", fen = "Deep examinations of the events less often heard from the War of the Ancients, and the impact they had on the future of Azeroth.", fua = "Глибокі дослідження менш відомих подій Війни Прадавніх та їхнього впливу на майбутнє Азероту." }
    t[140094] = { name = "Прадавня Магія і Як Володіти Нею, Не Знищивши Світ", fen = "A compendium of knowledge accumulated from many great Archmages of the Kirin Tor, with thorough retellings of the follies that have befallen reckless mages in times past.", fua = "Збірник знань, накопичених багатьма великими верховними магами Кірін-Тору, з докладними переказами безумств, що спіткали необачних магів у минулі часи." }
    t[140095] = { name = "Про Мор, Прокляття та Пошесті", fen = "Grim records of many of the more tragic events to have befallen Azeroth, and the powers that begat them, as recorded by Royal Historian Archesonus.", fua = "Похмурі записи багатьох найтрагічніших подій, що спіткали Азерот, та сил, які їх породили, занотовані королівською історикинею Архесонус." }
    t[140096] = { name = "Скверний Фоліант Воргалуса Дора", fen = "Demonic scrawlings of the departed warlock Vorgalus Dor, recounting many ancient and powerful weapons that originated on far away Legion worlds.", fua = "Демонічні записи покійного чорнокнижника Воргалуса Дора, що оповідають про багато прадавніх і могутніх видів зброї, які походять з далеких світів Легіону." }
    t[140097] = { name = "Падіння Лордерону та Спустошення Східних Земель", fen = "Historic records of the final days of the human kingdom of Lordaeron, recorded by Royal Historian Archesonus.", fua = "Історичні записи про останні дні людського королівства Лордерон, занотовані королівською історикинею Архесонус." }
    t[140098] = { name = "Останні Рештки Іллідарі", fen = "An examination of Illidan's defeat at Black Temple, and speculation on the fates of missing Demon Hunters that were under his training.", fua = "Дослідження поразки Іллідана біля Чорного Храму та припущення про долі зниклих мисливців на демонів, що навчалися під його керівництвом." }
    t[140099] = { name = "Кодекс Мертвих", fen = "A nathrezim text, all but indecipherable to the mortal races of Azeroth.", fua = "Текст натрезимів, майже неможливий для розшифрування смертними народами Азероту." }
    t[140100] = { name = "Скверний Фоліант Воргалуса Дора", fen = "Demonic scrawlings of the departed warlock Vorgalus Dor, recounting many ancient and powerful weapons that originated on far away Legion worlds.", fua = "Демонічні записи покійного чорнокнижника Воргалуса Дора, що оповідають про багато прадавніх і могутніх видів зброї, які походять з далеких світів Легіону." }
    t[140101] = { name = "Гіпотетичне Дослідження Слабкостей Легіону", fen = "Author unknown, originating from an unknown world, this work would surely be burned by the Legion wherever they encounter it.", fua = "Автор невідомий, походить з невідомого світу. Цей твір Легіон неодмінно спалив би, де б його не знайшов." }
    t[140102] = { name = "Експедиція Альянсу на Дренор", fen = "The story of the small expedition of Alliance heroes that ventured through the Dark Portal, many to never return.", fua = "Оповідь про невеликий загін героїв Альянсу, які наважилися пройти крізь Темний Портал, і багато з яких так і не повернулися." }
    t[140103] = { name = "Таємниці Диких Богів", fen = "Accounts and sightings of the numerous wild gods of Azeroth, spanning thousands of years of accumulated history.", fua = "Свідчення та спостереження численних диких богів Азероту, що охоплюють тисячі років зібраної історії." }
    t[140104] = { name = "Облудний Хранитель", fen = "Researched historical accounts about the events surrounding Loken's betrayal of his fellow keepers, by historian Llore.", fua = "Досліджені історичні свідчення про події навколо зради Локена своїм побратимам-хранителям, від історика Ллора." }
    t[140105] = { name = "Нерозказані Оповіді Війни Прадавніх", fen = "Deep examinations of the events less often heard from the War of the Ancients, and the impact they had on the future of Azeroth.", fua = "Глибокі дослідження менш відомих подій Війни Прадавніх та їхнього впливу на майбутнє Азероту." }
    t[140106] = { name = "Жертва Імператора Шаохао", fen = "The story of Shaohao's great sacrifice, and the generations that followed with no ruler.", fua = "Оповідь про велику жертву Шаохао та про покоління, що настали по тому без правителя." }
    t[140107] = { name = "Кодекс Мертвих", fen = "A nathrezim text, all but indecipherable to the mortal races of Azeroth.", fua = "Текст натрезимів, майже неможливий для розшифрування смертними народами Азероту." }
    t[140108] = { name = "За Престолом Повітря", fen = "History of the reign of the air elementals, the time of their banishing, and the eternal conflict of the elemental lords.", fua = "Історія владарювання повітряних елементалів, час їхнього вигнання та вічна боротьба володарів стихій." }
    t[140109] = { name = "Як Медитувати в Урагані", fen = "Instructions on the art of surrounding oneself with peace, even amidst great external turmoil, by Master Xunsu.", fua = "Настанови з мистецтва оточувати себе спокоєм навіть посеред великого зовнішнього сум'яття, від майстра Ксунсу." }
    t[140110] = { name = "Liber Monasterium", fen = "A holy text, of which only 12 copies were ever produced, many of which are thought to have been destroyed since.", fua = "Священний текст, якого було виготовлено лише 12 примірників, і багато з них, як вважають, відтоді знищено." }
    t[140111] = { name = "Війна Вінтерскорнів", fen = "Translated text from several earthen tablets, detailing an ancient vrykul war.", fua = "Перекладений текст із кількох земляних табличок, що оповідає про прадавню війну вріколів." }
    t[140112] = { name = "Доба Галакронда", fen = "Enticing tales of the first dragons, the keepers of Ulduar, and how power came to the five dragon aspects, by historian Evelyna.", fua = "Захопливі оповіді про перших драконів, хранителів Ульдуара й про те, як п'ять драконячих аспектів здобули свою силу, від історикині Евеліни." }
    t[140113] = { name = "Легенди Срібної Длані", fen = "Historical legends that extend back to the dawn of humanity, detailing the suspected origins of paladins and their relationship with the Light, by historian Evelyna.", fua = "Історичні легенди, що сягають світанку людства, з описом імовірного походження паладинів та їхнього зв'язку зі Світлом, від історикині Евеліни." }
    t[140114] = { name = "Дотик Безодні", fen = "Forbidden teachings of delving into the powers of the void, and turning their dangers into weapons, by Natalie Seline.", fua = "Заборонені вчення про занурення в сили Порожнечі та перетворення їхніх небезпек на зброю, від Наталі Селін." }
    t[140115] = { name = "Зіпсуття Ередарів і Втеча Дренеїв", fen = "An ancient text brought to Azeroth by the draenei, but lost in their first months outside the Exodar.", fua = "Прадавній текст, привезений на Азерот дренеями, але втрачений у перші місяці поза Екзодаром." }
    t[140116] = { name = "Загибель Модґуд", fen = "A grim tale of a Dark Iron sorceress that acquired a tool of the Old Gods, only to inevitibly fall to its corruption.", fua = "Похмура повість про чаклунку з клану Темного Заліза, яка здобула знаряддя Прадавніх Богів лише для того, щоб неминуче піддатися його скверні." }
    t[140117] = { name = "Полювання на Гнів Світла", fen = "Compiled by the Kirin Tor of Dalaran, warning of the dangers of powerful unstable weapons, even in the hands of experienced mages.", fua = "Укладено Кірін-Тором Даларану як застереження про небезпеку могутньої нестабільної зброї навіть у руках досвідчених магів." }
    t[140118] = { name = "День, Коли Прийшла Орда", fen = "A personal account of the first conflicts between humans and orcs, written by an advisor to King Llane of Stormwind.", fua = "Особисте свідчення про перші сутички між людьми та орками, написане радником короля Ллейна зі Стормвінду." }
    t[140119] = { name = "Кодекс Мертвих", fen = "A nathrezim text, all but indecipherable to the mortal races of Azeroth.", fua = "Текст натрезимів, майже неможливий для розшифрування смертними народами Азероту." }
