    t[193856] = { name = "Граблі Квітоньки", fen = "This rake is sturdy and surprisingly aerodynamic.", fua = "Ці граблі міцні й напрочуд аеродинамічні." }
    t[193892] = { name = "Свисток Бажанки", fen = "Target a lost argali and blow the whistle to call Wish!", fua = "Візьміть на приціл загублену аргалі й дмухніть у свисток, щоб покликати Бажанку!" }
    t[193908] = { name = "Кобальдт", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[193915] = "Прапор Чорного Драконячого Роду"
    t[194021] = { name = "Гербований Пергамент: Нижня Половина", fen = "The left side of the map is completely illegible, covered by a dark stain, as if someone's hand, full of ink, was intentionally dragged over the area to hide something.", fua = "Ліва частина карти геть нерозбірлива, вкрита темною плямою, наче хтось навмисно провів по цій ділянці рукою, замащеною чорнилом, щоб щось приховати." }
    t[194022] = { name = "Гербований Пергамент: Верхня Половина", fen = "Expansive waters cover the top of the parchment, with various volcanic depictions and winding rivers throughout.", fua = "Верх пергаменту вкривають широкі води з різними зображеннями вулканів та звивистими ріками." }
    t[194023] = { name = "Карта Скарбів: Береги Пробудження", fen = "The dark stain in the lower left portion of the map remains. Whatever resides in the area is surely meant to be left unfound.", fua = "Темна пляма в нижній лівій частині карти лишається. Те, що мешкає в цій місцині, напевно, не варто знаходити." }
    t[194024] = { name = "Рунозв'язаний Пергамент: Верхня Половина", fen = "Winding rivers marked by large, head-like symbols are scattered across the parchment.", fua = "По пергаменту розкидані звивисті ріки, позначені великими символами, схожими на голови." }
    t[194025] = { name = "Рунозв'язаний Пергамент: Нижня Половина", fen = "The text beneath the map is largely faded and unrecognizable. A large spire, swirling with energy appears in the bottom left of the parchment.", fua = "Текст під картою здебільшого вицвів і не розбірливий. У нижньому лівому кутку пергаменту з'являється велика вежа, оповита виром енергії." }
    t[194026] = { name = "Карта Скарбів: Лазурова Просторінь", fen = "Winding rivers cover the map. Several head-like symbols appear at various locations. A very large spire, swirling with energy sits alone to the southwest.", fua = "Карту вкривають звивисті ріки. У різних місцях з'являються кілька символів, схожих на голови. Дуже велика вежа, оповита виром енергії, самотньо височіє на південному заході." }
    t[194027] = { name = "Стародавній Пергамент: Верхня Половина", fen = "The upper left corner is marked by an imprint of a disc along with a large, temple-like structure in the middle of the map.", fua = "Верхній лівий кут позначено відбитком диска, а посеред карти - велика храмоподібна будівля." }
    t[194028] = { name = "Стародавній Пергамент: Нижня Половина", fen = "The ink on the map appears to be moving as swirls of black slowly drift across a mountainous region.", fua = "Чорнило на карті наче рухається, бо вири чорного повільно пливуть гористою місцевістю." }
    t[194029] = { name = "Карта Скарбів: Тальдраскус", fen = "The swirling ink snaps into position, revealing a large, central area with several surrounding structures, a disc with geometric shapes in the top left corner, and a large, temple-like structure in the middle of the map.", fua = "Кружляюче чорнило завмирає на місцях, відкриваючи велику центральну ділянку з кількома спорудами навколо, диск з геометричними фігурами у верхньому лівому кутку та велику храмоподібну будівлю посеред карти." }
    t[194085] = { name = "Доказ Могутності", fen = "Return this token to the Shikaar Master of Might to prove your prowess in the grand hunt.", fua = "Поверніть цей жетон Майстрові Могутності шікаарів, щоб довести свою вправність у великому полюванні." }
    t[194086] = { name = "Доказ Хитрості", fen = "Return this token to the Shikaar Master of Cunning to prove your prowess in the grand hunt.", fua = "Поверніть цей жетон Майстрині Хитрості шікаарів, щоб довести свою вправність у великому полюванні." }
