    t[194519] = "Допомога Осорії"
    t[194540] = { name = "Нотатки Зброяра Нохудів", fen = "The shipment is ready. Your weapons have been secured in the Hold until your return.\n\n\n\n<The ink used in the signature resembles dried blood.>\n\n\n\n- Graath", fua = "Вантаж готовий. Твою зброю замкнено в Трюмі до твого повернення.\n\n\n\n<Чорнило, яким зроблено підпис, нагадує засохлу кров.>\n\n\n\n— Ґраат" }
    t[194701] = "Зловісна Мушля"
    t[194889] = { name = "Набір Керованої Ракети XD-57 \"У Яблучко\"", fen = "For ages 5 and up.", fua = "Для віку від 5 років." }
    t[194890] = { name = "Мікрореактивний Ранець GG-117", fen = "Caution: aim away from face.", fua = "Обережно: спрямовуйте подалі від обличчя." }
    t[195044] = "Спробуй Ще Раз"
    t[195453] = { name = "Карта Схованки Лудо", fen = "The map shows a secret dig spot that only the dog knows of.", fua = "Карта показує таємне місце для розкопок, про яке знає лише пес." }
    t[197708] = { name = "Нестабільне Ядро Матриці", fen = "Warm. Volatile. Dangerous?", fua = "Тепле. Мінливе. Небезпечне?" }
    t[197733] = { name = "Нестійке Ядро Стримування", fen = "Harnessing so much energy in such a seemingly small fashion only lasts so long...", fua = "Утримання такої кількості енергії в настільки скромному вмістилищі триває недовго..." }
    t[197802] = "zzDog Bone (DNT - Reward PH)"
    t[198080] = { name = "Сигіл Бур", fen = "The illegible markings and fluctuating temperature of the sigil make this quite an interesting find.", fua = "Нерозбірливі позначки та мінлива температура сигілу роблять його доволі цікавою знахідкою." }
    t[198134] = { name = "Блискуча Підзорна Труба Дослідника", fen = "As good as new... should fetch a nice price.", fua = "Як новенька... має принести непогані гроші." }
    t[198141] = "Астральна Сутність"
    t[198350] = "Свіжий Рибний Стейк"
    t[198352] = { name = "Сигіл Бур", fen = "The illegible markings and fluctuating temperature of the sigil make this quite an interesting find.", fua = "Нерозбірливі позначки та мінлива температура сигілу роблять його доволі цікавою знахідкою." }
    t[198442] = { name = "Зменшувач Богтвотла", fen = "The scratched lettering on the label reads, 'Only the finest ingredients from, er... trust me. It's delicious!'.", fua = "Подряпаний напис на етикетці промовляє: «Лише найкращі інгредієнти з, е-е... повірте мені. Це смакота!»." }
    t[198538] = { name = "Магічно Запечатане Послання", fen = "The mysterious parchment emanates a mesmerizing purple colored dust slowly outward, where it dissipates after a fleeting moment.", fua = "Загадковий пергамент повільно випускає назовні зачаровуючий пил фіолетового кольору, що за коротку мить розсіюється." }
    t[198541] = { name = "Вичерпані Фіолетові Випари", fen = "The remnants of the message feels weightless. A flowery scent lingers.", fua = "Рештки послання здаються невагомими. Лишається квітковий аромат." }
    t[198605] = { name = "Заряджена Посудина Тайнознавства", fen = "The energy contained within is unimaginably powerful.", fua = "Енергія, що криється всередині, неймовірно могутня." }
    t[198622] = { name = "Спірагос", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[198725] = { name = "Сірий Мармоні", fen = "Teaches you how to summon a Gray Marmoni.", fua = "Навчає викликати сірого мармоні." }
    t[198726] = { name = "Чорний Дріботряс", fen = "Teaches you how to summon a Black Skitterbug.", fua = "Навчає викликати чорного дріботряса." }
    t[198843] = { name = "Нотатки Дослідника Смарагдових Садів", fen = "I saw a glint of green passing by one of the caves in the Emerald Gardens. It could be a precious gem! Or just another sleeping dragon...", fua = "Я помітив зблиск зеленого біля однієї з печер у Смарагдових Садах. Це може бути коштовний самоцвіт! Або просто черговий сплячий дракон..." }
    t[198852] = { name = "Наказ Знищити Ведмедя", fen = "The amber gems we were searching for were spotted in a cave. Unfortunately, that cave appears to be the den of a rather unfriendly bear. Take it out, and we can finally get to those gems.", fua = "Бурштинові самоцвіти, які ми шукали, помітили в печері. На жаль, ця печера, схоже, є лігвом доволі непривітного ведмедя. Прикінчіть його, і ми нарешті дістанемося до тих самоцвітів." }
    t[198854] = { name = "Нотатки Археолога про Артефакти", fen = "Detailed research findings that indicate a possible treasure location near the Wingrest Embassy.", fua = "Докладні дослідницькі висновки, що вказують на можливе місце скарбу поблизу Посольства Крилоспокою." }
    t[198858] = { name = "Заряджена Посудина Тайнознавства", fen = "The enchanted aura surrounding the vessel appears to be waning.", fua = "Зачарована аура навколо посудини, схоже, згасає." }
    t[199061] = { name = "Путівник по Рідкісних Рибах", fen = "The Bubble Drifter is a particularly timid fish, but is attracted to certain pecular scents.", fua = "Бульбашковий Дрейфувальник — особливо боязка риба, але її приваблюють певні дивні запахи." }
    t[199062] = { name = "Карта Рубінового Скупчення Самоцвітів", fen = "Long ago, clusters of ruby gems would grow within the Ruby Life Pools and surrounding areas. See if you can find one such cluster.", fua = "Колись давно скупчення рубінових самоцвітів виростали в Рубінових Озерах Життя та довколишніх краях. Спробуй знайти одне таке скупчення." }
    t[199065] = { name = "Скорботний Лист", fen = "Well, my proposal failed... The jewel lies at the bottom of a crystal waterfall where I threw it if you want it back.\n\n\n\n- Dongi", fua = "Що ж, моя пропозиція провалилася... Самоцвіт лежить на дні кришталевого водоспаду, куди я його жбурнув, — якщо хочеш його забрати.\n\n\n\n— Донґі" }
    t[199066] = { name = "Застережний Лист", fen = "A letter of warning seemingly written by Gnolls to warn against an aggressive enemy.", fua = "Застережний лист, схоже, написаний ґнолами, щоб попередити про агресивного ворога." }
    t[199067] = { name = "Коштовні Креслення", fen = "The precious sapphires within the Dragon Isles are very rare and can be difficult to obtain. The best place to look would be the snowy regions, although I have to warn you, there are many monstrous creatures in those areas.", fua = "Дорогоцінні сапфіри Драконячих Островів дуже рідкісні, і їх буває важко роздобути. Найкраще шукати в засніжених регіонах, хоча мушу тебе попередити: у тих краях багато жахливих створінь." }
    t[199068] = { name = "Загублена в Часі Записка", fen = "A torn note containing multiple entries with dates out of order...", fua = "Подерта записка з кількома записами, дати яких ідуть не по порядку..." }
    t[199069] = { name = "Карта Йенну", fen = "The \"map\" looks like a large sandy circle with hastily drawn lines and circles.", fua = "«Карта» виглядає як велике піщане коло з нашвидкуруч намальованими лініями та колами." }
    t[199109] = { name = "Первісний Штормик", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
