    t[205366] = { name = "Глиняний Горщик, з Якого Капає", fen = "This sealed pot contains a strange, slippery mud.", fua = "У цьому запечатаному горщику дивна слизька грязюка." }
    t[205795] = { name = "Звивистий Черв'як", fen = "A rather fat worm wriggles around in your palm.", fua = "Доволі гладкий черв'як звивається в тебе на долоні." }
    t[205900] = { name = "Мерехтливий Драконовий Самоцвіт", fen = "A shimmering ruby sits in a beautiful gold setting of draconic origin. Perhaps someone in Loamm might be interested?", fua = "Мерехтливий рубін у гарній золотій оправі драконового походження. Можливо, хтось у Лоаммі ним зацікавиться?" }
    t[205901] = { name = "Хрусткий Жук", fen = "The brilliant red hue of this beetle's shell conjures images of apples and cherries.", fua = "Яскраво-червоний відтінок панцира цього жука викликає в уяві образи яблук і вишень." }
    t[205902] = { name = "Кіготь Глибинного Шкуродера", fen = "This crystalline claw is razor sharp!", fua = "Цей кристалічний кіготь гострий, мов бритва!" }
    t[205906] = { name = "Пернатий Друг", fen = "This stuffed duck toy is well-worn. It was clearly beloved by its past owner.", fua = "Ця плюшева качечка добряче потерта. Попередній власник вочевидь дуже її любив." }
    t[205907] = { name = "Просяклий Тотем", fen = "This strange effigy is soaked through, as if it has just been dunked in water. It also emanates a strong fishy odor.", fua = "Це дивне зображення наскрізь просякло водою, ніби його щойно занурювали в неї. До того ж від нього тхне рибою." }
    t[205909] = { name = "Натягнуте Полотно", fen = "A beautiful piece of stretched canvas that could be useful as a drum, or maybe a scent painting.", fua = "Гарне натягнуте полотно, яке згодилося б для барабана чи, може, для запахового живопису." }
    t[205910] = { name = "Булькітливий Еліксир", fen = "The liquid inside this ornate container smells like blueberries and seawater. It's bubbling so fiercly that it sounds like it's hissing.", fua = "Рідина в цій оздобленій посудині пахне чорницею та морською водою. Вона так сильно булькоче, що це нагадує сичання." }
    t[205911] = { name = "Загадкові Пахощі", fen = "This is definitely incense, but it smells completely different from Loamm's!", fua = "Це безперечно пахощі, але вони пахнуть зовсім не так, як лоаммські!" }
    t[205912] = { name = "Обтягнута Шкірою Фляга", fen = "It smells like this flask is empty, but the faint traces of a pungent beverage still remain.", fua = "Пахне так, ніби ця фляга порожня, але ледь чутні сліди терпкого напою досі лишилися." }
    t[205913] = { name = "Порожній Записник", fen = "A rather large book that is blank. (By niffen standards.)", fua = "Доволі великий записник, який є порожнім. (За мірками ніффенів.)" }
